const e={lerninhalte:{"unternehmensfuehrung-ueberblick":{schritte:[{titel:"What is management?",blocks:[{type:"begriff",term:"Management",erklaerung:"Means two things: the PEOPLE who run a company (managers) and the PROCESS of managing (management process)."},{type:"text",text:"Main task: securing the company's success – not just day to day, but above all in the long term and sustainably."},{type:"kette",glieder:[{titel:"From the vision …",wert:"Normative"},{titel:"… through the strategy …",wert:"Strategic"},{titel:"… to putting it into practice",wert:"Operational"}]},{type:"tabelle",spalten:["Level","Deals with …"],zeilen:[["Normative management","vision, norms, values and goals (mission statement)"],["Strategic management","long-term planning, company strategies"],["Operational management","putting the goals and strategies into practice in a targeted way"]]},{type:"text",text:"Ship example: the captain wants to reach New York safely (vision) → sets purpose and guidelines (normative) → works out the plan with the first officer (strategic) → the officer monitors the voyage (operational)."}]},{titel:"Levels of hierarchy",blocks:[{type:"pyramide",stufen:[{name:"Top management",beispiel:"Managing directors – overall responsibility"},{name:"Middle management",beispiel:"Heads of department – link between top and bottom"},{name:"Lower management",beispiel:"Team/group leaders – operational tasks"},{name:"Operating level",beispiel:"Employees put decisions into practice"}]},{type:"merke",text:"The higher the level, the fewer managers. Normative + strategic → top and middle management. Operational → lower management. Small businesses often have only 1–2 levels."},{type:"begriff",term:"CEO, CSO, COO",erklaerung:"Chief Executive Officer (managing director) · Chief Sales Officer (head of sales) · Chief Operating Officer (day-to-day business)."}]},{titel:"Communication in the company",blocks:[{type:"begriff",term:"Communication as a management task",erklaerung:"Making sure information is exchanged successfully between managers and employees and between teams and departments."},{type:"tabelle",spalten:["Success factor","Meaning"],zeilen:[["Clarity","clear and understandable, no misunderstandings"],["Openness","open and honest about goals, successes, problems → trust"],["Regularity","information reliably and on time through fixed channels"],["Empathy","taking employees' needs into account"]]},{type:"begriff",term:"Digital tools",erklaerung:"Microsoft Teams (chat, video calls), Slack, intranet (internal platform), newsletter tools."}]}],zusammenfassung:[{titel:"Management",punkte:["Management = people (managers) + the process of managing","Normative (vision, values, mission statement) → strategic (long-term strategies) → operational (putting it into practice)","Hierarchy: top, middle, lower management, operating level (pyramid)","Communication: clarity, openness, regularity, empathy; digital tools"]}]},"normatives-management":{schritte:[{titel:"The mission statement",blocks:[{type:"begriff",term:"Normative management",erklaerung:`Sets the company's "rules of the game" so that it acts responsibly and in the long term.`},{type:"begriff",term:"Mission statement",erklaerung:"The written purpose of the company, its beliefs and goals. A guide for management and stakeholders."},{type:"kette",glieder:[{titel:"Vision + mission + philosophy",wert:"Company goals"},{titel:"influences",wert:"Corporate culture"}]},{type:"vergleich",frage:"Functions of the mission statement:",links:{titel:"Internal effect",punkte:["Motivation","Sense of belonging","Communicating goals"]},rechts:{titel:"External effect",punkte:["Positive image","Credibility","Attractive to new employees"]}}]},{titel:"Vision, mission, philosophy",blocks:[{type:"tabelle",spalten:["Component","Question","Example"],zeilen:[["Vision","Where does the company want to go? (picture of the future)",`Instagram: "Capture and share the world's moments."`],["Mission","Why does it exist? (purpose, benefit)",'Netflix: "To entertain the world."'],["Company philosophy","Which values are important?",'Post AG: "We are yellow, green, colourful."'],["Company goals","What does it want to achieve in the future?","Market share +7%"]]},{type:"merke",text:"Vision = lighthouse (picture of the future). Mission = the contribution the company makes. Not every company has a vision, but every company has a mission."},{type:"begriff",term:"Claim vs. slogan",erklaerung:'Claim = long-term, expresses the mission/USP ("Education that inspires!"). Slogan = shorter-term, refers to single products.'},{type:"begriff",term:"Corporate Social Responsibility (CSR)",erklaerung:"The company's voluntary responsibility for society and the environment – values must show in concrete actions."},{type:"tabelle",spalten:["CSR guideline","Meaning"],zeilen:[["ESG criteria","Environmental, Social, Governance – required report for large EU companies (from 250 employees)"],["SDGs","17 sustainability goals of the UN"],["ISO 26000","international CSR standard with 7 principles"],["UN Global Compact","voluntary pact: 10 principles (human rights, labour, environment)"]]}]},{titel:"Company goals",blocks:[{type:"vergleich",frage:"1. By time frame:",links:{titel:"Strategic goals",punkte:["Long-term (approx. 5 years)","Put vision and mission into practice","e.g. customer satisfaction +10% in 5 years"]},rechts:{titel:"Operational goals",punkte:["Short- to medium-term","Put strategic goals into practice concretely","e.g. answer enquiries within 3 days"]}},{type:"vergleich",frage:"2. By type of goal:",links:{titel:"Monetary goals",punkte:["Measurable in money","e.g. revenue +10%"]},rechts:{titel:"Non-monetary goals",punkte:["Not measurable in money","e.g. flexible working hours"]}},{type:"tabelle",spalten:["3. Operationalisation","Question","Example"],zeilen:[["Goal content","What?","Increase market share"],["Goal extent","How much?","7%"],["Deadline","By when?","December this year"],["Responsibility","Who?","Head of sales"],["Goal location","Where?","Indian market"]]},{type:"tabelle",spalten:["4. Relationship between goals","Meaning","Example"],zeilen:[["Goal neutrality","they don't affect each other","ergonomic workplaces ↔ cutting logistics costs"],["Goal complementarity (harmony)","one supports the other","customer satisfaction ↑ → revenue ↑"],["Goal conflict (competition)","one gets in the way of the other","securing jobs ↔ cutting staff costs"]]}]},{titel:"Corporate culture",blocks:[{type:"begriff",term:"Corporate culture",erklaerung:"Determines how people think and act in the company: the values that are shared, LIVED and accepted. Shows whether the mission statement is really lived."},{type:"tabelle",spalten:["Measures for a positive culture"],zeilen:[["Open exchange across all levels of hierarchy"],["Rituals (shared lunch breaks, team meetings, company events)"],["Real work-life balance (flexible hours, home office, health)"],["Managers authentically set an example of the values"]]}]}],zusammenfassung:[{titel:"Mission statement",punkte:["Mission statement = vision + mission + company philosophy → company goals → influences culture","Functions: internal effect (motivation) + external effect (image)","Vision = picture of the future · mission = purpose/benefit · philosophy = values","CSR = responsibility to society; ESG, SDGs, ISO 26000, UN Global Compact"]},{titel:"Goals & culture",punkte:["Strategic (long-term) ↔ operational (short/medium-term) · monetary ↔ non-monetary","Operationalisation: content, extent, deadline, responsibility, location (+ SMART)","Relationships between goals: neutrality, complementarity, conflict","Corporate culture = values that are actually lived"]}]},"strategisches-operatives-management":{schritte:[{titel:"The management cycle",blocks:[{type:"begriff",term:"Management process",erklaerung:"The goals from normative management are put into practice through strategic and operational management – in a cycle."},{type:"zyklus",mitte:"Management cycle",schritte:["Strategic + operational planning","Decision","Implementation","Monitoring (variance analysis)"]},{type:"ablauf",titel:"Developing a strategy",schritte:[{titel:"Guidelines from normative management",text:"vision, values, long-term goals"},{titel:"External + internal analysis",text:"environment/industry + internal situation"},{titel:"Forecasts",text:"future developments"},{titel:"SWOT analysis",text:"bring everything together"},{titel:"Develop possible strategies"}]}]},{titel:"External analysis",blocks:[{type:"begriff",term:"PESTEL analysis (environment analysis)",erklaerung:"Examines what influence the environment has and which opportunities and risks arise."},{type:"tabelle",spalten:["Factor","Example"],zeilen:[["P – Political","customs duties are raised"],["E – Economic","raw material costs rise"],["S – Sociocultural","trend towards healthy eating"],["T – Technological","AI increases productivity"],["E – Ecological (environmental)","stricter environmental rules"],["L – Legal","new minimum wage"]]},{type:"begriff",term:"Five forces model (Porter)",erklaerung:"Industry analysis: five forces determine how strong competition is in an industry."},{type:"tabelle",spalten:["Force","Is strong when …"],zeilen:[["Bargaining power of suppliers","there are few suppliers, switching is difficult"],["Bargaining power of customers","few buyers, switching is easy (comparison websites)"],["Threat of new competitors","entering the market is easy, hardly any barriers to entry"],["Threat of substitutes","real alternatives (oat milk instead of cow's milk)"],["Rivalry among existing competitors","many similar suppliers, slow market growth"]]},{type:"merke",text:"High competitive intensity = industry usually less profitable. Substitutes = replacement products with a similar function."}]},{titel:"Internal analysis & forecasts",blocks:[{type:"begriff",term:"Internal analysis",erklaerung:"Examines strengths and weaknesses (production, staff, finance, organisation). Tools: internal audits and benchmarking."},{type:"begriff",term:"Benchmarking",erklaerung:"Comparison with the BEST competitor. The result is often shown as a strengths-weaknesses profile.",beispiel:"Zalando compares its returns processes with Amazon's."},{type:"vergleich",frage:"Forecasting methods:",links:{titel:"Scenario technique",punkte:["3 possible pictures of the future:","Best case (positive)","Realistic case (trend)","Worst case (negative)"]},rechts:{titel:"Delphi method",punkte:["Experts are asked in several rounds","Answers summarised and assessed again","→ more and more accurate estimate"]}}]},{titel:"SWOT analysis",blocks:[{type:"begriff",term:"SWOT analysis",erklaerung:"Brings together opportunities & threats (external) and strengths & weaknesses (internal). This results in 4 strategic directions."},{type:"tabelle",spalten:["","Strengths (S)","Weaknesses (W)"],zeilen:[["Opportunities (O)","S-O: use strengths to seize opportunities","W-O: overcome weaknesses to use opportunities"],["Threats (T)","S-T: use strengths to fend off threats","W-T: reduce weaknesses so they don't become threats"]]},{type:"merke",text:"S = strengths, W = weaknesses (internal) · O = opportunities, T = threats (external)."}]},{titel:"Strategies",blocks:[{type:"tabelle",spalten:["Competitive strategy (Porter)","Meaning","Example"],zeilen:[["Cost leadership","lowest costs → lowest prices","KiK"],["Differentiation","unique (quality, brand) → higher prices","Gucci"],["Niche strategy","focus on one part of the market","Patagonia"]]},{type:"tabelle",spalten:["Portfolio (BCG)","Recommendation"],zeilen:[["Question marks","invest or divest"],["Stars","growth strategy – support strongly"],["Cash cows",'harvesting strategy – "milk" them'],["Poor dogs","divestment strategy – take off the market"]]},{type:"formel",name:"Relative market share",zaehler:"own absolute market share",nenner:"market share of the largest competitor",beispiel:"> 1.0 = market leader"},{type:"tabelle",spalten:["Growth (Ansoff)","existing target group","new target group"],zeilen:[["Existing product","Market penetration (more advertising, quantity discount)","Market development (new countries, uses)"],["New product","Product development (Coca-Cola Zero)","Diversification (Coca-Cola buys Costa Coffee)"]]}]},{titel:"Operational planning, decision & monitoring",blocks:[{type:"begriff",term:"Operational planning",erklaerung:"In detail: who does what, when, how, with what and where? The heart of it is budgeting."},{type:"begriff",term:"Budgeting",erklaerung:"Sets financial resources (payments, costs) and target results (revenue). Partial budgets (materials, staff, sales …) → overall budget. Controlling checks that it is kept to."},{type:"vergleich",links:{titel:"Bottom-up",punkte:["Department heads create partial budgets","→ combined into the overall budget","For separate departments"]},rechts:{titel:"Top-down",punkte:["Management sets the overall budget","→ partial budgets derived from it","For dependent departments"]}},{type:"tabelle",spalten:["Successful decisions"],zeilen:[["Weigh things up rationally"],["Keep the overall goals in mind"],["Define minimum criteria"],["Collect relevant information"],["Play through scenarios"],["Bring in outside advice"],["Choose individual or group decision"]]},{type:"begriff",term:"Monitoring (variance analysis)",erklaerung:"Compare results with goals, look for reasons for deviations, take action. Monitoring of results, procedures and behaviour."},{type:"zyklus",mitte:"PDCA (Deming cycle)",schritte:["Plan – set goals","Do – put into practice","Check – monitor","Act – adjust"]},{type:"merke",text:"PDCA = continuous improvement. Needs a culture that deals openly with mistakes."}]}],zusammenfassung:[{titel:"Strategic planning",punkte:["Cycle: planning → decision → implementation → monitoring","External: PESTEL (political, economic, social, technological, ecological, legal) + five forces model","Internal: audits, benchmarking (strengths-weaknesses profile)","Forecasts: scenario technique (best/realistic/worst) · Delphi method (experts, several rounds)","SWOT: S-O, W-O, S-T, W-T strategies"]},{titel:"Strategies",punkte:["Porter: cost leadership · differentiation · niche","BCG: question marks, stars, cash cows, poor dogs","Ansoff: market penetration, market development, product development, diversification"]},{titel:"Operational & monitoring",punkte:["Budgeting: partial plans → overall budget; bottom-up ↔ top-down","Monitoring = variance analysis (results, procedures, behaviour)","PDCA: Plan → Do → Check → Act"]}]},"organisieren-und-fuehren":{schritte:[{titel:"Organisational structure & process organisation",blocks:[{type:"begriff",term:"Company organisation",erklaerung:"Regulates the STRUCTURE of the company (organisational structure) and the PROCESSES (process organisation). The two are closely linked."},{type:"vergleich",links:{titel:"Organisational structure",punkte:["Structure: who is responsible for what?","Tasks → departments → positions"]},rechts:{titel:"Process organisation",punkte:["Processes: what, in which order, how, where?","Within the set structure"]}},{type:"kette",glieder:[{titel:"e.g. planning a trade fair stand",wert:"Task"},{titel:"several tasks",wert:"Department"},{titel:"within the department",wert:"Position"}]},{type:"begriff",term:"Position",erklaerung:"Basic element of the organisational structure: the tasks that belong to the work area of ONE person."},{type:"tabelle",spalten:["Type of position","Authority","Example"],zeilen:[["Management position (line authority)","leading, giving instructions, deciding, monitoring","Managing directors, heads of department"],["Staff position","no authority to give instructions, advises and supports","Assistant, controlling, legal department"],["Operating position","decides only in its own area, no instructions","Clerk, accountant"]]},{type:"vergleich",links:{titel:"Centralisation",punkte:["A few people make all the important decisions"]},rechts:{titel:"Decentralisation",punkte:["Decisions delegated to many people","Management only ensures that information is exchanged"]}}]},{titel:"Management systems (organisation chart)",blocks:[{type:"tabelle",spalten:["","Single-line system","Multi-line system"],zeilen:[["Principle","each position has only ONE superior","each position has TWO or more superiors"],["Forms","functional (by purchasing, production …) or divisional (by divisions: countries, products)","Matrix organisation (functions AND divisions)"],["Advantages","clear, clear responsibility, clear chain of command","short information paths, fast communication, takes pressure off management"],["Disadvantages","long communication paths, pressure on upper levels","contradicting instructions, unclear, many managers"]]},{type:"merke",text:"Organisation chart = graphic picture of the organisational structure. Staff positions can be used in both systems."},{type:"begriff",term:"Agile organisation",erklaerung:"Can react quickly to changes: customer focus (along the customer journey), flat hierarchies, self-organised teams."}]},{titel:"Process organisation & processes",blocks:[{type:"begriff",term:"Process",erklaerung:"Chain of connected activities that together create customer benefit."},{type:"tabelle",spalten:["Type of process","Meaning","Example"],zeilen:[["Business processes","core business","Production, marketing, sales"],["Support processes","support the business processes","Human resources, IT"],["Management processes","steering and leading","Planning processes"]]},{type:"begriff",term:"Flowchart",erklaerung:"Shows processes with symbols: start/end (rounded), process (rectangle), decision (diamond), flow line (arrow)."}]},{titel:"Leadership theories",blocks:[{type:"begriff",term:"Leading employees & leadership style",erklaerung:"Leading employees = influencing employees' behaviour to reach goals. Leadership style = the manager's long-term pattern of behaviour."},{type:"tabelle",spalten:["Theory","Success factor","Examples"],zeilen:[["Trait theories","the manager's personality","intelligence, assertiveness, empathy, self-confidence"],["Behavioural theories","behaviour (leadership style)","classic leadership styles, managerial grid"],["Situational theories","behaviour depending on the situation","maturity theory, Vroom-Yetton model"]]},{type:"tabelle",spalten:["Leadership style (Lewin)","Feature","+","−"],zeilen:[["Authoritarian","decides alone","fast decisions, clear responsibilities","overloaded manager, demotivated employees"],["Cooperative","employees take part in decisions","motivation, team spirit","decisions take longer"],["Laissez-faire","only steps in when there are problems","freedom, creativity","employees overwhelmed, loss of control"]]},{type:"begriff",term:"Managerial grid",erklaerung:"Two dimensions from 1–9: task orientation and people orientation."},{type:"tabelle",spalten:["Position","Name","Meaning"],zeilen:[["1.1","Impoverished management","hardly any interest in tasks or people"],["9.1","Authority-compliance management","strong task orientation, strict control"],["1.9","Country club management","feel-good atmosphere, little performance"],["5.5","Middle-of-the-road management","the middle way"],["9.9","Team management","ideal: performance AND motivation"]]}]},{titel:"Situational theories & management concepts",blocks:[{type:"begriff",term:"Situational leadership theory (Hersey/Blanchard)",erklaerung:"Leadership style depends on the employees' maturity level (ability + motivation)."},{type:"ablauf",titel:"From low to high maturity",schritte:[{titel:"Telling",text:"low maturity: exact instructions, control"},{titel:"Selling",text:"low–medium maturity: explain tasks, strongly people-focused"},{titel:"Participating",text:"medium–high maturity: involve them in decisions"},{titel:"Delegating",text:"high maturity: hand over tasks without detailed explanation"}]},{type:"begriff",term:"Vroom-Yetton model",erklaerung:"Leadership behaviour depends on decision quality (how important is the right solution?) and employee acceptance (how important is agreement?)."},{type:"tabelle",spalten:["Type of decision","Meaning"],zeilen:[["AI / AII – authoritarian","alone (AII: after gathering information)"],["BI / BII – with consultation","alone after discussing with one person (BI) / with the group (BII)"],["GII – group","everyone decides together"]]},{type:"tabelle",spalten:["Management concept","Meaning"],zeilen:[["Management by delegation","own area of responsibility; management only steps in when there are problems"],["Management by results","only results count (set and checked)"],["Management by objectives","goals are agreed TOGETHER"],["Management by motivation","incentives based on employees' needs"]]}]}],zusammenfassung:[{titel:"Organisation",punkte:["Organisational structure (structure: task → department → position) + process organisation (processes)","Positions: line authority (management), staff position (advice, no instructions), operating position","Centralisation ↔ decentralisation","Single-line system (functional/divisional) ↔ multi-line system (matrix)","Agile: customer focus, flat hierarchies, self-organised teams","Processes: business, support, management processes; flowchart"]},{titel:"Leadership",punkte:["Trait, behavioural, situational theories","Leadership styles: authoritarian, cooperative, laissez-faire","Managerial grid: 1.1, 9.1, 1.9, 5.5, 9.9 (ideal)","Maturity theory: telling → selling → participating → delegating","Vroom-Yetton: decision quality + acceptance → AI, AII, BI, BII, GII","Management by delegation, results, objectives, motivation"]}]},personalbedarfsplanung:{schritte:[{titel:"Tasks of HR management",blocks:[{type:"begriff",term:"Human resource management (HR)",erklaerung:"Takes care of the employees = a company's most important capital (human capital)."},{type:"ablauf",titel:"Overview of tasks",schritte:[{titel:"Workforce planning",text:"How many employees with which qualifications are needed when and where?"},{titel:"Recruiting and selection",text:"attract and choose suitable employees"},{titel:"Staff development",text:"train and qualify employees"},{titel:"Staff release",text:"ending employment relationships"},{titel:"Designing staff deployment",text:"framework for motivated work"}]}]},{titel:"Determining & covering staff needs",blocks:[{type:"vergleich",links:{titel:"Quantitative staff need",punkte:["HOW MANY employees?","Varies with season, absences (illness, parental leave, resignation), demand"]},rechts:{titel:"Qualitative staff need",punkte:["WHICH qualifications?","Education, experience, personality, social skills","Written in the job description"]}},{type:"begriff",term:"Job description",erklaerung:"Contains all the important information about a position: place in the organisation, objective, tasks, powers."},{type:"merke",text:"Also: local staff need (where?) and time-related staff need (when, how long?)."},{type:"tabelle",spalten:["Situation","Measure"],zeilen:[["Need > current staff","Recruiting and selection OR staff development"],["Need < current staff","Staff release OR staff development (retraining)"]]}]},{titel:"Recruiting",blocks:[{type:"ablauf",titel:"Recruiting and selection process",schritte:[{titel:"Set the requirements profile",text:"general requirements, education, personality, industry knowledge"},{titel:"Recruiting"},{titel:"Pre-selection",text:"analyse application documents"},{titel:"Selection",text:"selection procedures"},{titel:"Hiring"}]},{type:"vergleich",links:{titel:"Internal recruiting",punkte:["Without staff movement: overtime, moving holidays, staff development","With staff movement: promotion, transfer, internal job posting"]},rechts:{titel:"External recruiting",punkte:["By the company: job ads, website, fairs","With third parties: AMS (public employment service), HR consultants, temporary staffing, job portals, headhunters"]}},{type:"tabelle",spalten:["Term","Meaning"],zeilen:[["Temporary staffing (staff leasing)",'company "borrows" staff short-term from a staffing agency'],["Headhunter","approaches highly qualified specialists directly"],["Employer branding","building an image as an attractive employer"]]},{type:"merke",text:"Job ad: information about the company, position, qualifications, salary (required!), how to apply. Must be gender-neutral (§ 9 Equal Treatment Act) – e.g. (m/f/d)."}]},{titel:"Pre-selection & selection",blocks:[{type:"begriff",term:"Application documents",erklaerung:"Cover letter (max. 1 page) + CV with photo + copies of certificates (school certificates and job references)."},{type:"tabelle",spalten:["In pre-selection the company checks"],zeilen:[["Are the most important criteria of the requirements profile met?"],["Do CV and certificates match?"],["Are there gaps in the career history?"],["Frequent job changes?"]]},{type:"tabelle",spalten:["Selection procedure","Meaning"],zeilen:[["Video application","short introduction video"],["Telephone interview","15–30 min., clarify the basics"],["Job interview","almost always: appearance, communication"],["Work samples","tasks from real work"],["Tests","e.g. intelligence tests"],["Assessment centre","several applicants, group tasks, up to 3 days – mainly for management positions"]]},{type:"ablauf",titel:"Structure of the job interview",schritte:[{titel:"Start of the interview (atmosphere)"},{titel:"Applicant introduces themselves"},{titel:"Company introduces itself"},{titel:"Questions about the CV"},{titel:"Situational questions"},{titel:"Open conversation"},{titel:"End of the interview"}]},{type:"merke",text:"Not allowed: questions about political party, religion, pregnancy or illnesses."}]},{titel:"Hiring & staff development",blocks:[{type:"begriff",term:"Employment record (Dienstzettel)",erklaerung:"Records the most important information from the employment contract. Required – except for max. 1 month or a written contract with all details. The employer registers the employee with the ÖGK (health insurance) before they start."},{type:"begriff",term:"Staff development (SD)",erklaerung:"All planned training and further education to develop professional, methodical, social and personal skills."},{type:"vergleich",links:{titel:"Company goals",punkte:["secure qualified staff","competitiveness","satisfaction & loyalty","independence from the labour market"]},rechts:{titel:"Individual goals",punkte:["personal growth","prestige","career opportunities","higher income"]}},{type:"tabelle",spalten:["Method","Examples"],zeilen:[["Into the job (preparation)","onboarding, trainee programme, apprenticeship, mentor/buddy"],["On the job (at the workplace)","instruction, coaching"],["Near the job (close to the workplace)","project work, quality circles, feedback talks"],["Off the job (outside)","e-learning, seminars, part-time studies"],["Along the job (career)","development talks, career planning"],["Out of the job (leaving)","retirement preparation, outplacement"]]}]},{titel:"Staff release",blocks:[{type:"tabelle",spalten:["Type of ending","Applies to","Meaning"],zeilen:[["Expiry","fixed-term","ends automatically"],["Ending in the probation period","probation period (max. 1 month, apprentices 3)","any time, no reason needed"],["Notice (termination)","permanent","either side, no reason, with notice period and date"],["Dismissal","always","employer, immediately, for serious misconduct (theft, refusing to work)"],["Resignation without notice (Austritt)","always","employee, immediately, for serious misconduct by the employer (no pay, harassment)"],["Termination by mutual agreement","always","both agree, no notice periods"]]},{type:"vergleich",links:{titel:"Notice by the employee",punkte:["on the last day of any month","notice period usually 1 month"]},rechts:{titel:"Notice by the employer (salaried employees)",punkte:["at the end of a quarter","1st–2nd year: 6 weeks","3rd–5th year: 2 months","6th–15th year: 3 months","16th–25th year: 4 months","from 26th year: 5 months"]}},{type:"begriff",term:"Termination date & notice period",erklaerung:"Date = the day the employment ends. Notice period = time between receiving the notice and the date.",beispiel:"Notice period 2 months, date 31 March → give notice by 31 January at the latest"},{type:"merke",text:"Protection against dismissal: expectant mothers, parental leave, military/civilian service, works council members, people with recognised disabilities."},{type:"tabelle",spalten:["Entitlement on leaving","Meaning"],zeilen:[["Pay & special payments","up to the last day + proportional special payments + payment for unused holiday"],["Job-search days","if the employer gives notice: 1/5 of weekly working hours off with pay"],["Job reference (Dienstzeugnis)","in writing: length and type of work, no negative wording"],["Severance pay (MVK)","1.53% of gross pay monthly; paid out after at least 3 years of payments"]]}]}],zusammenfassung:[{titel:"Planning & recruiting",punkte:["Staff need: quantitative (how many) + qualitative (which qualifications, job description) + local + time-related","Need > current → recruiting or development · need < current → release or retraining","Recruiting: requirements profile → search → pre-selection → selection → hiring","Internal (promotion, transfer) ↔ external (job ads, AMS, temporary staffing, headhunters)"]},{titel:"Selection & hiring",punkte:["Documents: cover letter, CV, certificates","Procedures: video, telephone, job interview, work sample, test, assessment centre","Employment record + registration with the ÖGK"]},{titel:"Development & release",punkte:["SD methods: into, on, near, off, along, out of the job","Ending: expiry, probation period, notice, dismissal, resignation without notice, mutual agreement","Employer gives salaried employees notice at end of quarter; notice period 6 weeks to 5 months","Entitlements: pay, special payments, payment for unused holiday, job-search days, job reference, severance pay (MVK 1.53%)"]}]},personaleinsatzgestaltung:{schritte:[{titel:"Hierarchy of the legal system",blocks:[{type:"begriff",term:"Rights and duties",erklaerung:"An employment relationship gives both sides rights and duties. They are found in different rules – ordered in a hierarchy."},{type:"ablauf",titel:"Hierarchy (labour law) – from top to bottom",schritte:[{titel:"EU law",text:"regulations, directives (EU)"},{titel:"National laws",text:"e.g. Salaried Employees Act, Working Hours Act, Holidays Act (parliament)"},{titel:"Collective agreement",text:"social partners (trade union + Chamber of Commerce): pay, working hours for an industry"},{titel:"Works agreements",text:"works council + employer, within one business"},{titel:"Individual employment contract",text:"employee + employer"}]},{type:"merke",text:"Lower levels may only differ if it is BETTER for employees. Salary in the employment contract may be higher than in the collective agreement – but never lower."}]},{titel:"Rights and duties",blocks:[{type:"vergleich",links:{titel:"Employer",punkte:["Paying wages/salary","Duty of care: protection from dangers, health, equal treatment, special protection (young people, pregnant women)"]},rechts:{titel:"Employee",punkte:["Doing the work personally","Duty of loyalty: confidentiality, no gifts, nothing that damages the reputation, non-competition"]}},{type:"merke",text:"Employee's duties = employer's rights and vice versa."},{type:"begriff",term:"Non-competition rule",erklaerung:"Without permission, the employee may neither run a business nor do business in the same line of trade for another company."}]},{titel:"Working hours, holidays, absence from work",blocks:[{type:"tabelle",spalten:["Rule","Content"],zeilen:[["Normal working hours","8 hrs/day, 40 hrs/week (collective agreement often 38.5); less = part-time"],["Flexitime","flexible within core working hours"],["Overtime","normal pay + 50% (100% at night, Sundays/public holidays) or time off in lieu"],["Maximum working hours","incl. overtime max. 12 hrs/day, 60 hrs/week"],["Rest breaks","more than 6 hrs → at least a 30-min break; afterwards 11 hrs rest"]]},{type:"begriff",term:"Holidays",erklaerung:"25 working days per working year (five-day week), from the 26th year 30. Full entitlement after 6 months. Holiday dates only by agreement."},{type:"begriff",term:"Absence from work",erklaerung:"Illness, accident → report immediately; pay continues. Sick note usually after 3 days. Also briefly for important personal reasons (wedding, death in the family)."},{type:"vergleich",links:{titel:"Maternity protection",punkte:["8 weeks before + 8 weeks after the birth","Complete ban on working","Maternity pay (Wochengeld) from the ÖGK"]},rechts:{titel:"Parental leave (Karenz)",punkte:["Afterwards, max. until the 2nd birthday","No wages, childcare benefit from the state","Parents can share it"]}}]},{titel:"Co-determination in the business",blocks:[{type:"kette",glieder:[{titel:"elect",wert:"All employees"},{titel:"represents the staff",wert:"Works council"},{titel:"all together",wert:"Staff meeting"}]},{type:"tabelle",spalten:["Body","Meaning"],zeilen:[["Works council","link between management and staff; from 5 employees (over 18)"],["Right to vote","from age 16"],["Right to be elected","from age 18 and 6 months in the business"],["Staff meeting","all staff, at least once a year; can remove the works council"]]}]},{titel:"Theories of motivation",blocks:[{type:"pyramide",stufen:[{name:"Self-actualisation",beispiel:"further training, career opportunities"},{name:"Esteem",beispiel:"praise, awards, bonuses"},{name:"Social needs",beispiel:"working atmosphere, team events"},{name:"Safety",beispiel:"fair pay, permanent contract"},{name:"Basic needs",beispiel:"drinks, lunch"}]},{type:"begriff",term:"Two-factor theory (Herzberg)",erklaerung:"Distinguishes motivators (create satisfaction) and hygiene factors (only prevent dissatisfaction)."},{type:"vergleich",links:{titel:"Motivators (intrinsic)",punkte:["Content of the work","Achievement, success, recognition","Responsibility, promotion","→ lead to satisfaction"]},rechts:{titel:"Hygiene factors (extrinsic)",punkte:["Working environment","Salary, working conditions, job security","Leadership style, colleagues","→ if missing, lead to dissatisfaction"]}},{type:"tabelle",spalten:["Motivating work organisation","Meaning"],zeilen:[["Job rotation","systematic change of workplace"],["Job enlargement","additional tasks with the SAME requirements"],["Job enrichment","tasks with HIGHER requirements and more responsibility"]]},{type:"tabelle",spalten:["Pleasant workplace design"],zeilen:[["Interesting work content (flexible hours, home office, four-day week)"],["Safe, pleasant working environment (ergonomics, accident prevention)"],["Health measures (fitness, yoga, healthy food)"],["Company benefits (pension scheme, public transport allowance, childcare)"]]}]}],zusammenfassung:[{titel:"Labour law",punkte:["Hierarchy: EU law → laws → collective agreement → works agreement → individual contract; differences only in the employee's favour","Employer: pay + duty of care · employee: work + duty of loyalty (non-competition)","Working hours: 8 h/40 h normal; max. 12 h/60 h; break from 6 h; overtime +50%","Holidays: 25 working days (from 26th year 30)","Maternity protection 8 + 8 weeks; parental leave until 2nd birthday","Works council from 5 employees; vote from 16, be elected from 18 + 6 months"]},{titel:"Motivation",punkte:["Maslow: basic, safety, social needs, esteem, self-actualisation","Herzberg: motivators (satisfaction) ↔ hygiene factors (prevent dissatisfaction)","Job rotation, job enlargement (same requirements), job enrichment (more responsibility)","Workplace: work content, environment, health, benefits"]}]},personalbeurteilung:{schritte:[{titel:"Generational diversity",blocks:[{type:"text",text:"Up to 5 generations meet in companies – each with its own values and expectations."},{type:"tabelle",spalten:["Generation","Born","Values","Expectations"],zeilen:[["Baby boomers","1946–1964","loyal, dutiful","security, recognition, clear hierarchies"],["Generation X","1965–1980","independent, pragmatic","development, work-life balance"],["Generation Y","1981–1995","team-oriented, tech-savvy","flexibility, meaning, flat hierarchies"],["Generation Z","1996–2010","digital, security-minded","structure, feedback, meaning"],["Generation Alpha","from 2010","digital, individualistic","having a say, digital working worlds"]]},{type:"begriff",term:"Sabbatical",erklaerung:"A longer, limited and unpaid break from work – especially attractive for younger generations."}]},{titel:"Pay",blocks:[{type:"begriff",term:"Remuneration",erklaerung:"Payment in return for work: wages (workers) or salary (salaried employees)."},{type:"tabelle",spalten:['"Fair" pay is …',"takes into account"],zeilen:[["performance-based","work results and performance"],["requirement-based","difficulty and effort"],["qualification-based","required qualifications"],["market-based","what others pay for the same position"],["socially fair","family status, age"]]},{type:"tabelle",spalten:["Form of pay","Meaning","Example"],zeilen:[["Time wage","pay per unit of time (hour, month)","Teacher"],["Piece-rate wage (performance pay)","linked to quantity: piece rate or time rate","Harvest helper per kg"],["Bonus wage (performance pay)","time wage + bonus for extra performance","Estate agent per property"]]},{type:"tabelle",spalten:["Social benefits","Example"],zeilen:[["Statutory","employer's share of social insurance"],["Collective agreement","dirt allowance, holiday and Christmas bonus"],["Voluntary","canteen, company car"]]},{type:"tabelle",spalten:["Employee participation","Meaning"],zeilen:[["Performance-related bonus","bonus for special achievements"],["Capital participation","employee shares, employee foundation"],["Profit sharing","share of the distributed profit"]]},{type:"merke",text:'"Cafeteria system": employees choose for themselves from different incentives (insurance, holidays, company car).'}]},{titel:"Staff appraisal",blocks:[{type:"begriff",term:"Staff appraisal",erklaerung:"Assessing employees' performance and potential → best possible use, fair pay, targeted support, motivation."},{type:"tabelle",spalten:["Form","Meaning"],zeilen:[["By managers","most common form"],["By colleagues","good insight, but tensions possible"],["Self-assessment","high acceptance, often differs from how others see you"],["360° feedback","from many sides: colleagues, managers, customers, suppliers"]]},{type:"tabelle",spalten:["Method","Meaning"],zeilen:[["Rating method","rate criteria on a scale"],["… with behaviour description","scale + examples of behaviour"],["Goal-oriented method","Were the agreed goals reached?"]]},{type:"merke",text:"Always combine with a talk (appraisal form). Don't rate traits that are not relevant to the work."},{type:"tabelle",spalten:["Appraisal error","Meaning"],zeilen:[["Halo effect",'one striking trait "outshines" everything else'],["Selective perception","you only see what confirms your own opinion"],["Similarity effect","similar people are rated better"],["Recency effect","what was seen most recently is overrated"]]}]},{titel:"Support functions",blocks:[{type:"begriff",term:"HR controlling",erklaerung:"Planning, steering and monitoring all staff-related activities. Checks how effective and efficient HR management is."},{type:"vergleich",links:{titel:"Quantitative methods",punkte:["Key figures: applicants per position, staff costs per employee, overtime, staff turnover rate, training costs"]},rechts:{titel:"Qualitative methods",punkte:["staff appraisals","employee surveys","potential analyses","strengths-weaknesses analyses"]}},{type:"formel",name:"Staff intensity",zaehler:"staff costs · 100",nenner:"operating performance"},{type:"begriff",term:"Personnel administration",erklaerung:"Administrative tasks: payroll (wages, travel expenses), reports (anniversaries, tax office), monitoring (working hours, overtime)."},{type:"vergleich",links:{titel:"Employer branding",punkte:["Long-term building of the employer brand","image campaigns, certificates, rating platforms, employees as brand ambassadors"]},rechts:{titel:"HR marketing",punkte:["Putting it into practice","careers website, social media, internships, recruiting fairs"]}}]}],zusammenfassung:[{titel:"Generations & pay",punkte:["Baby boomers, X, Y, Z, Alpha – different values and expectations","Fair pay: performance-, requirement-, qualification-, market-based, socially fair","Time wage · piece-rate wage (piece/time rate) · bonus wage","Social benefits: statutory, collective agreement, voluntary · employee participation: performance, capital, profit"]},{titel:"Appraisal",punkte:["By managers, colleagues, self, 360° feedback","Rating method (± behaviour description), goal-oriented","Errors: halo effect, selective perception, similarity effect, recency effect"]},{titel:"Support",punkte:["HR controlling: quantitative (key figures) + qualitative (surveys)","Staff intensity = staff costs · 100 / operating performance","Personnel administration: payroll, reports, monitoring","Employer branding (employer brand) → HR marketing (concrete measures)"]}]},produktionsbetriebe:{schritte:[{titel:"Importance of production businesses",blocks:[{type:"begriff",term:"Production business (manufacturing business)",erklaerung:"Companies from industry and trades that make physical goods. They belong to the secondary sector (with construction and mining)."},{type:"begriff",term:"Gross domestic product (GDP)",erklaerung:"Total value of all goods and services produced in a country in one year."},{type:"tabelle",spalten:["Sector","Share of GDP (Austria)","Share of employees"],zeilen:[["Primary (raw materials)","approx. 1%","approx. 3%"],["Secondary (production)","approx. 28%","approx. 25%"],["Tertiary (services)","approx. 71%","approx. 71%"]]},{type:"merke",text:"About 70% of Austrian exports come from the production sector. Over 95% of production businesses are small and medium-sized businesses."}]},{titel:"Types of production businesses",blocks:[{type:"vergleich",frage:"By type of customer:",links:{titel:"Consumer goods businesses",punkte:["Physical goods for consumers (end users)","e.g. furniture, drinks"]},rechts:{titel:"Capital goods businesses",punkte:["Physical goods for other companies","e.g. conveyor belt, robots, steel sheets"]}},{type:"tabelle",spalten:["Criterion","Trade business (craft)","Industrial business"],zeilen:[["Main factor","materials and labour","fixed assets (high fixed costs)"],["Business size","small and medium-sized businesses","medium-sized and large businesses"],["Management","owner","management"],["Manufacturing","little automation, little division of labour","high degree of automation, a lot of division of labour"],["Example","Naturbackstube Honeder (bakery)","industrial bakery backaldrin"]]},{type:"merke",text:"Trade = labour-intensive. Industry = equipment-intensive. The line between them is not always clear."}]},{titel:"Goals of production businesses",blocks:[{type:"begriff",term:"Competitiveness",erklaerung:"Production businesses must make sellable, unique products (unique selling point/USP) and react flexibly to changes."},{type:"tabelle",spalten:["Goals of company production"],zeilen:[["Optimal use of the factors of production (productivity, efficiency, profitability)"],["Customer satisfaction"],["Low production costs"],["Sustainable and ethical production"]]},{type:"begriff",term:"Fixed cost degression",erklaerung:"The more units are produced, the lower the fixed costs per unit (mass production).",beispiel:"IKEA produces Billy shelves in huge quantities."},{type:"tabelle",spalten:["Sustainability","Meaning"],zeilen:[["People – social","fair working environment, health, further training"],["Planet – ecological","renewable energy, energy efficiency, less water use"],["Profit – economic","doing business responsibly: laws, no corruption, fair competition"]]}]},{titel:"Choosing a location",blocks:[{type:"begriff",term:"Location",erklaerung:"Geographic place of a business. Choosing a location is an important strategic decision – long-term, expensive and hard to reverse."},{type:"tabelle",spalten:["Location factors","Examples"],zeilen:[["Procurement-related","land, infrastructure, workers, closeness to suppliers/raw materials, rents, research"],["Production-related","legal regulations, taxes, bureaucracy, staff costs, subsidies"],["Sales-oriented","closeness to customers, competition, transport links, image"]]},{type:"merke",text:"For production businesses, procurement-related and production-related factors matter most (e.g. location on rivers for transporting raw materials). Tool: scoring method."},{type:"begriff",term:"Follow-the-customer principle",erklaerung:"Setting up production where the most important customers are.",beispiel:"voestalpine is expanding in the USA to be close to lorry manufacturers and avoid customs duties."}]}],zusammenfassung:[{titel:"Production businesses",punkte:["Produce physical goods (industry, trades) – secondary sector, approx. 28% of GDP, approx. 70% of exports","Consumer goods (end users) ↔ capital goods businesses (companies)","Trade (labour-intensive, owner, small) ↔ industry (equipment-intensive, management, large, automated)"]},{titel:"Goals & location",punkte:["Competitiveness through USP and flexibility","Goals: optimal use of factors, customer satisfaction, low costs, sustainability (people, planet, profit)","Fixed cost degression: more units → lower fixed costs per unit","Location factors: procurement-related, production-related, sales-oriented; follow-the-customer"]}]},"leistungserstellungsprozess-produktion":{schritte:[{titel:"The process at a glance",blocks:[{type:"begriff",term:"Production",erklaerung:"The factors of production labour, equipment and materials are combined so that products are made."},{type:"ablauf",titel:"Production process",schritte:[{titel:"Product innovation",text:"(further) development of a product"},{titel:"Sales planning",text:"estimate how many products can be sold"},{titel:"Production programme planning",text:"which products, when and how many?"},{titel:"Material requirements planning",text:"work out the materials needed"},{titel:"Scheduling",text:"set the concrete work steps"},{titel:"Carrying out production",text:"decide on manufacturing options"}]},{type:"merke",text:"Production controlling and quality management run alongside. In practice a PPC system (e.g. SAP) helps."}]},{titel:"Product innovation",blocks:[{type:"begriff",term:"Product innovation",erklaerung:"A completely new product is created or an existing one is developed further. Requires investment in research and development (R&D)."},{type:"kette",glieder:[{titel:"1",wert:"Product proposal"},{titel:"2",wert:"Development (design)"},{titel:"3",wert:"Preparing production"}]},{type:"text",text:"Alongside: cost controlling (salaries, equipment, market research)."},{type:"vergleich",frage:"Where does the idea come from?",links:{titel:"Technology push",punkte:["a new technology triggers innovation","e.g. AI → chatbots"]},rechts:{titel:"Market pull",punkte:["a customer wish/trend triggers innovation","e.g. vegan products"]}},{type:"tabelle",spalten:["Term","Meaning"],zeilen:[["Technical drawing","graphic picture of the product"],["Product structure","tree: product → assemblies (A) → individual parts (P)"],["Bill of materials","list of all assemblies and individual parts with quantities"],["Simultaneous engineering","developing product and manufacturing at the same time"]]},{type:"begriff",term:"Preparing production",erklaerung:"Work planning → providing the factors of production → tests (prototype)."}]},{titel:"Sales & production programme planning",blocks:[{type:"begriff",term:"Sales planning",erklaerung:"Estimates which products will probably be sold in which quantity (primary demand). Basis: sales statistics, market research."},{type:"begriff",term:"Production programme planning",erklaerung:"Sets: type of products, quantity and timing. Checks whether there is enough capacity."},{type:"vergleich",links:{titel:"Make to order",punkte:["production only when there is a concrete customer order","customer wishes possible","e.g. injection moulding machine"]},rechts:{titel:"Make to stock",punkte:["production based on forecast sales","always able to deliver","e.g. detergent, drinks"]}},{type:"formel",name:"Contribution margin",zaehler:"revenue − variable costs",nenner:"1",beispiel:"Optimal production programme = contribution margin/profit at its maximum"},{type:"begriff",term:"Capacity",erklaerung:"A company's ability to produce (equipment, machines, human work)."}]},{titel:"Material requirements planning",blocks:[{type:"begriff",term:"Material requirements planning",erklaerung:"Works out the materials needed based on the production programme and makes them available on time."},{type:"tabelle",spalten:["Calculation"],zeilen:[["materials needed per bill of materials · production quantity"],["= gross requirement (total requirement)"],["− stock"],["= net requirement (actually to be obtained)"]]},{type:"text",text:"Example carpentry: 120 tables · 4 table legs = 480 table legs (gross) − 75 in stock = 405 table legs (net)."},{type:"vergleich",links:{titel:"In-house production",punkte:["net requirement is produced in-house"]},rechts:{titel:"Buying in",punkte:["net requirement is bought in"]}}]},{titel:"Scheduling",blocks:[{type:"vergleich",links:{titel:"Lead time scheduling",punkte:["order based on the tasks to be done","set start and end dates"]},rechts:{titel:"Capacity scheduling",punkte:["takes the available capacity into account","capacity profiles"]}},{type:"tabelle",spalten:["Lead time","consists of"],zeilen:[["Processing time","set-up time (preparing the machine) + operation time"],["Transition time","idle time (nothing happens) + transport time"]]},{type:"tabelle",spalten:["","Forward scheduling","Backward scheduling"],zeilen:[["How it works","start immediately after the order arrives → earliest possible end date","calculate back from the delivery date → latest possible start"],["Advantage","little time pressure","lower storage costs"],["Disadvantage","capital tied up in stock","no time buffer"]]},{type:"merke",text:"Chronological: bar chart (Gantt). Parallel steps: network plan. Delivery reliability = on-time deliveries · 100 / total number."},{type:"formel",name:"Utilisation in %",zaehler:"capacity demand · 100",nenner:"capacity available"},{type:"tabelle",spalten:["Adjusting when overloaded","Examples"],zeilen:[["Time-based","overtime, moving delivery dates"],["Quantitative","extra machines, more staff"],["Intensity-based","increasing productivity (technology, training)"]]}]},{titel:"Carrying out production",blocks:[{type:"tabelle",spalten:["Type of manufacturing","Feature","+","−"],zeilen:[["Single-unit production","one item to customer specification (cruise ship)","exactly as wanted, high quality","high costs, long lead time"],["Batch production","limited number of identical/similar products (car series)","lower unit costs","high capital need, not very flexible"],["Mass production","identical products in any quantity (mineral water)","low costs, fast","changeover expensive, high storage costs"]]},{type:"tabelle",spalten:["Type of organisation","Feature","Example"],zeilen:[["Workshop production","same activities in one workshop","metal fence: cutting, drilling, painting"],["Assembly line production","stations in order, automatic transport","TV sets"],["Group production","mix of workshop and assembly line","sofa: frame, padding, cover"],["Site production","everything is brought to the site","tunnel construction"]]},{type:"merke",text:"Type of manufacturing = HOW MANY identical products. Type of organisation = HOW the workstations are arranged."}]},{titel:"Production controlling & quality",blocks:[{type:"begriff",term:"Production controlling",erklaerung:"A separate process alongside production: analyses deviations and room for improvement (budgets, target/actual comparisons, capacity and bottleneck checks)."},{type:"zyklus",mitte:"Control loop",schritte:["Plan goals","Set targets","Target/actual comparison","Problem analysis","Corrective measures","Review"]},{type:"begriff",term:"Quality management",erklaerung:"Customer focus at the centre: quality is systematically monitored, analysed and improved."},{type:"kette",glieder:[{titel:"Customer wishes",wert:"Customer-oriented quality"},{titel:"basis for",wert:"Technical quality"},{titel:"both fulfilled",wert:"Good product"}]},{type:"tabelle",spalten:["Quality area","Meaning"],zeilen:[["Product and service quality","quality of the end product/service"],["Process quality","error-free, cost-effective production"],["System quality","quality of the management system (e.g. ISO 9001)"]]},{type:"ablauf",titel:"Stages of quality management (since 1950)",schritte:[{titel:"Quality control",text:"samples of finished products, sort out faulty ones"},{titel:"Quality assurance",text:"monitor the production process, spot errors already during production"},{titel:"Total quality management",text:"based on customer needs, all processes geared to quality"},{titel:"Business excellence",text:"best management for all stakeholders, constant improvement"}]}]}],zusammenfassung:[{titel:"Process",punkte:["Product innovation → sales planning → production programme planning → material requirements planning → scheduling → carrying out production","Innovation: product proposal → development → preparation; technology push ↔ market pull","Product structure (product → A → P), bill of materials","Make to order ↔ make to stock; contribution margin = revenue − variable costs","Net requirement = bill of materials · quantity − stock"]},{titel:"Time & production",punkte:["Lead time = set-up + operation + idle + transport time","Forward (earliest end date) ↔ backward scheduling (latest start)","Capacity scheduling: utilisation = demand · 100 / available; adjust by time, quantity, intensity","Types of manufacturing: single-unit, batch, mass production","Types of organisation: workshop, assembly line, group, site production"]},{titel:"Controlling & quality",punkte:["Production controlling: control loop with target/actual comparison","Quality: customer-oriented + technical; product/service, process, system quality (ISO 9001)","Stages: quality control → quality assurance → total QM → business excellence"]}]},"investition-finanzierung-ueberblick":{schritte:[{titel:"Financial planning",blocks:[{type:"begriff",term:"Financial planning",erklaerung:"A clear overview of current and future capital needs and financing options. The basis for investing money efficiently."},{type:"tabelle",spalten:["Management level","Financial planning"],zeilen:[["Normative","set long-term financial goals"],["Strategic","budget planning, assessing investment projects (e.g. new technology to reduce CO₂)"],["Operational","ongoing cost control, securing liquidity for salaries and invoices"]]},{type:"begriff",term:"Liquidity",erklaerung:"The company's ability to make its payments on time."}]},{titel:"Investment & financing in the balance sheet",blocks:[{type:"vergleich",links:{titel:"Assets",punkte:["Fixed assets: intangible assets, property, plant and equipment, financial assets","Current assets: stock, receivables, cash, bank balances","→ use of funds = INVESTMENT"]},rechts:{titel:"Liabilities & equity = capital",punkte:["Equity: contributions, profit, reserves","Debt: provisions, loans, liabilities","→ source of funds = FINANCING"]}},{type:"merke",text:"Total assets = total capital. Investment = WHAT the money is used for (assets). Financing = WHERE the money comes from (liabilities & equity)."},{type:"kette",glieder:[{titel:"Where from? (liabilities & equity)",wert:"Financing"},{titel:"makes possible",wert:"→"},{titel:"What for? (assets)",wert:"Investment"}]}]}],zusammenfassung:[{titel:"Overview",punkte:["Financial planning = overview of capital needs and financing options; at all management levels","Liquidity = ability to pay","Balance sheet: assets (= use of funds = investment) ↔ liabilities & equity (capital = source of funds = financing)","Fixed assets (long-term) + current assets (short-term) = equity + debt"]}]},investitionsmanagement:{schritte:[{titel:"Types of investment",blocks:[{type:"begriff",term:"Investment",erklaerung:"Using financial resources to acquire assets. Wrong decisions can even lead to insolvency (inability to pay)."},{type:"vergleich",frage:"Types of investment:",links:{titel:"By type of asset",punkte:["Real investment: physical (machine)","Financial investment: securities","Intangible investment: patents"]},rechts:{titel:"By reason for investment",punkte:["New investment: founding/first time","Replacement investment: like-for-like replacement","Rationalisation investment: more efficient","Expansion investment: more capacity"]}}]},{titel:"Investment process",blocks:[{type:"begriff",term:"Investment management",erklaerung:"Systematic planning, decision-making, implementation and monitoring of investments."},{type:"ablauf",titel:"Investment process (example: new stove in a hotel)",schritte:[{titel:"Investment planning",text:"report the need, set decision criteria, get quotes"},{titel:"Investment decision",text:"assess investments, check financing, decide to buy"},{titel:"Implementation",text:"order, payment"},{titel:"Monitoring",text:"goals reached? corrections, experience for the future"}]},{type:"vergleich",frage:"Decision criteria:",links:{titel:"Quantitative (hard facts)",punkte:["Can be measured in numbers","costs, revenue, profit, capital employed, profitability, payback period"]},rechts:{titel:"Qualitative (soft facts)",punkte:["Cannot be measured in numbers","environmental friendliness, quality, reliability, service, occupational safety"]}}]},{titel:"Overview of tools",blocks:[{type:"tabelle",spalten:["Static method","Question","Decision for …"],zeilen:[["Cost comparison method","Which investment causes the lowest costs?","lowest costs"],["Profit comparison method","Which earns the highest profit?","highest profit"],["Profitability comparison method","Which has the highest return on capital?","highest profitability"],["Payback method","Where does the capital flow back fastest?","shortest payback period"]]},{type:"merke",text:"Static methods = only quantitative criteria, calculate with average values for ONE period. Scoring method = qualitative criteria too."}]},{titel:"Cost comparison method",blocks:[{type:"begriff",term:"Cost comparison method",erklaerung:"Compares the average costs per period. The alternative with the lowest costs is chosen."},{type:"tabelle",spalten:["Total costs","consist of"],zeilen:[["Running operating costs","variable (e.g. fuel) + fixed (insurance, maintenance)"],["+ capital costs","imputed interest + imputed depreciation"],["= total costs","basis for comparison with the same output"]]},{type:"formel",name:"Imputed interest",zaehler:"(acquisition cost + residual value)",nenner:"2",faktor:"· interest rate"},{type:"formel",name:"Imputed depreciation",zaehler:"acquisition cost − residual value",nenner:"useful life"},{type:"formel",name:"Unit costs",zaehler:"total costs",nenner:"output quantity",beispiel:"compare when output quantities differ"},{type:"formel",name:"Critical quantity",zaehler:"difference in fixed costs per period",nenner:"difference in variable costs per unit",beispiel:"(292,500 − 221,000) / (150 − 110) = 1,787.5 hours"},{type:"merke",text:"Critical quantity (when utilisation is unknown): above it, the alternative with lower variable costs is worth it; below it, the one with lower fixed costs. Residual value = value at the end of the useful life."}]},{titel:"Profit & profitability comparison",blocks:[{type:"begriff",term:"Profit comparison method",erklaerung:"Adds revenue to the cost comparison method. For investments with different capacity or quality. Highest profit wins."},{type:"formel",name:"Profit",zaehler:"revenue − total costs",nenner:"1"},{type:"begriff",term:"Profitability comparison method",erklaerung:"Adds the capital employed to the profit comparison method. Highest profitability (return on capital) wins."},{type:"formel",name:"Profitability",zaehler:"(profit + imputed interest) · 100",nenner:"Ø capital employed",beispiel:"Ø capital employed = (acquisition cost + residual value) / 2"},{type:"formel",name:"Profitability (without profit)",zaehler:"cost savings · 100",nenner:"Ø capital employed"}]},{titel:"Payback method",blocks:[{type:"begriff",term:"Payback method",erklaerung:"Over what period does the capital invested flow back through profits or savings? The shorter, the lower the risk."},{type:"vergleich",links:{titel:"Average method",punkte:["Annual cash inflow is the same"]},rechts:{titel:"Cumulative method",punkte:["Annual cash inflows differ","Inflows are added up until they cover the costs"]}},{type:"formel",name:"Payback period",zaehler:"acquisition cost − residual value",nenner:"annual profit + imputed depreciation",beispiel:"250,000 / (75,000 + 25,000) = 2.5 years"},{type:"formel",name:"Payback period (savings)",zaehler:"acquisition cost − residual value",nenner:"annual cost savings"},{type:"merke",text:"The payback period should be within the useful life. But it says nothing about long-term profit."}]},{titel:"Limits & scoring method",blocks:[{type:"tabelle",spalten:["Limit of static methods","Solved by"],zeilen:[["Only one period considered","dynamic methods (several periods)"],["Same costs and revenue assumed","dynamic methods (compounding/discounting)"],["Not very meaningful","dynamic methods"],["Only hard facts","scoring method (soft facts too)"]]},{type:"begriff",term:"Time value of money",erklaerung:"An amount of money today is worth more than the same amount in the future (inflation)."},{type:"ablauf",titel:"Scoring method (utility analysis)",schritte:[{titel:"Set criteria",text:"quantitative AND qualitative"},{titel:"Weight criteria",text:"together 100%"},{titel:"Rate alternatives with points"},{titel:"points × weighting, add up"},{titel:"Highest utility value wins"}]}]}],zusammenfassung:[{titel:"Basics",punkte:["Type of asset: real, financial, intangible investment","Reason: new, replacement, rationalisation, expansion investment","Process: planning → decision → implementation → monitoring","Criteria: quantitative (hard facts) ↔ qualitative (soft facts)"]},{titel:"Static methods",punkte:["Cost comparison: lowest costs; total costs = operating costs + imputed interest + imputed depreciation","Imputed interest = (AC + RV) / 2 · interest rate · imputed depreciation = (AC − RV) / useful life","Critical quantity = Δ fixed costs / Δ variable costs","Profit comparison: profit = revenue − total costs","Profitability = (profit + imputed interest) · 100 / Ø capital employed","Payback period = (AC − RV) / (profit + imputed depreciation); average ↔ cumulative method"]},{titel:"Limits",punkte:["Static: 1 period, constant values, no time value of money, only hard facts","Solution: dynamic methods + scoring method (weighted points)"]}]},finanzmanagement:{schritte:[{titel:"Financing goals & tasks",blocks:[{type:"begriff",term:"Financing",erklaerung:"Planning and providing the capital needed to start, keep up and expand business activities."},{type:"kette",glieder:[{titel:"Which investment?",wert:"Investment management"},{titel:"fit together like puzzle pieces",wert:"+"},{titel:"How to pay?",wert:"Financial management"}]},{type:"tabelle",spalten:["Financing goal","Meaning"],zeilen:[["Liquidity","being able to make payments on time and in full"],["Profitability","how much return the capital employed earns"],["Independence","through a high share of equity; otherwise investors want a say"]]},{type:"formel",name:"Profitability",zaehler:"profit",nenner:"capital employed",faktor:"· 100"},{type:"merke",text:"Goal conflict liquidity ↔ profitability: if a lot of money is invested (return ↑), it may be missing for invoices (liquidity ↓) – and vice versa."},{type:"tabelle",spalten:["Tasks of financial management"],zeilen:[["Work out the ongoing financing need (financial planning)"],["Decide on the type of financing"],["Financial analysis with key figures"],["Carry out financing (payments, raising capital, invoices)"]]}]},{titel:"Overview of types of financing",blocks:[{type:"text",text:"Types of financing are divided by 2 criteria:"},{type:"vergleich",links:{titel:"Origin of the capital",punkte:["Internal financing: from the company's own business activities","External financing: from outside investors/lenders"]},rechts:{titel:"Legal position of the capital provider",punkte:["Equity financing: equity (owners)","Debt financing: debt (creditors)"]}},{type:"tabelle",spalten:["","Internal financing","External financing"],zeilen:[["Equity financing","Self-financing","Contribution/participation financing, other forms of participation, subsidies"],["Mixed form","Reallocation financing","Mezzanine capital"],["Debt financing","Financing from provisions","Loan financing, bonds"]]},{type:"merke",text:"This table is the heart of the chapter – every type of financing has exactly one place in it!"}]},{titel:"Equity financing",blocks:[{type:"begriff",term:"Equity financing",erklaerung:"The company receives additional equity – from retained profits (internal) or from owners/partners (external)."},{type:"vergleich",links:{titel:"Advantages of high equity",punkte:["Independence","No interest","Losses easier to cover (less risk of insolvency)","Better creditworthiness"]},rechts:{titel:"Equity providers …",punkte:["are directly involved","have a right to information","have influence on management","share in the profit","share the risk"]}},{type:"merke",text:"Guideline: equity ratio at least 20%."},{type:"vergleich",frage:"Self-financing (from the company's own strength):",links:{titel:"Open self-financing",punkte:["profits are not paid out, they stay in the company","capital account or reserves"]},rechts:{titel:"Hidden self-financing",punkte:["hidden reserves through accounting rules (assets valued too low, liabilities too high)","profit only arises when they are released"]}},{type:"begriff",term:"Contribution and participation financing",erklaerung:"Capital from outside, but owners' equity. Contributions: sole traders. Participation: OG, KG, GesbR, GmbH, AG (shares), cooperative."},{type:"tabelle",spalten:["Other form of participation","Meaning"],zeilen:[["Venture capital (risk capital)","a financing company gives young companies equity (usually from €200,000) in return for shares and a say"],["Business angels","experienced private individuals: capital (approx. €50,000–150,000) + know-how + contacts"],["Crowdfunding","many private individuals (the crowd) pay small amounts via platforms"],["Going public (IPO)","conversion into an AG and first stock market listing"],["Employee participation","employees receive shares (e.g. FlexKapG company value shares)"]]},{type:"tabelle",spalten:["Crowdfunding model","Return"],zeilen:[["Donation-based","none – money for a good cause"],["Reward-based","reward (e.g. the product)"],["Lending-based","interest + repayment (counts as debt!)"],["Equity-based (crowdinvesting)","share in the company and profit"]]},{type:"begriff",term:"Subsidies (grants)",erklaerung:'"Free money" from the federal government, provinces, municipalities, EU or WKO: grants, cheap loans, guarantees, fee exemptions, subsidised advice. They never cover the whole need.'}]},{titel:"Reallocation financing",blocks:[{type:"begriff",term:"Reallocation financing",erklaerung:"Mix of equity and debt financing: money tied up in the business is released."},{type:"tabelle",spalten:["Type","How it works","Example"],zeilen:[["Rationalisation","optimise processes, use the capital saved","reduce stock through just-in-time"],["Depreciation","depreciation included in the selling price → flows back, can be used until replacement","machine €100,000 / 10 years = €10,000 per year"],["Selling assets","sell assets that aren't needed","sell an unused plot of land"]]}]},{titel:"Debt financing & loans",blocks:[{type:"begriff",term:"Debt – features",erklaerung:"Only for a limited time · interest · creditors have no say and no share in increases in value · creditors are paid FIRST in bankruptcy."},{type:"begriff",term:"Financing from provisions (internal)",erklaerung:"Provisions for expected expenses (unclear when and how much – e.g. lawsuits, warranties, pensions). The money is available until it is needed."},{type:"begriff",term:"Loan",erklaerung:"The borrower (debtor) borrows money from the lender (creditor) for a certain period. Repayment + interest."},{type:"tabelle",spalten:["Distinguished by …","Options"],zeilen:[["Lender","private individuals, banks, the state, companies (suppliers)"],["What is provided","money, goods, liability"],["Term","short-term (≤ 1 year), medium-term (1–5), long-term (> 5)"],["Purpose","fixed assets, current assets, bridging finance, consumption"],["Loan security","personal security, real security, credit insurance"]]}]},{titel:"Loan security & credit check",blocks:[{type:"begriff",term:"Guarantee (personal security)",erklaerung:"A third person (guarantor) is liable for the loan with their private assets."},{type:"tabelle",spalten:["Type of guarantee","The guarantor is liable …"],zeilen:[["Deficiency guarantee","only for the remainder after all legal steps (e.g. enforcement) – limited"],["Ordinary guarantee","if reminders to the main debtor are unsuccessful"],["Joint and several guarantee",'as "guarantor and payer" – creditor can choose immediately – far-reaching']]},{type:"tabelle",spalten:["Real security","Meaning"],zeilen:[["Retention of title","goods belong to the seller until paid in full"],["Assignment of receivables (cession)","customer receivables are assigned to the lender (open or silent)"],["Lien","Lombard (movable goods: gold, securities) · mortgage (land, in the land register)"]]},{type:"ablauf",titel:"How loan transactions work",schritte:[{titel:"Loan application",text:"with documents (bank statements, salary / balance sheets, financial plans, company register extract)"},{titel:"Credit check",text:"creditworthiness via rating: hard facts (income, assets) + soft facts (payment behaviour, management)"},{titel:"Loan agreement",text:"sign contract + security documents"},{titel:"Loan monitoring",text:"watch accounts, turnover, balance sheets (early warning system)"}]},{type:"merke",text:"The better the creditworthiness, the cheaper the loan. Best rating: AAA (triple A), worst: D (default)."}]},{titel:"Types of loan",blocks:[{type:"tabelle",spalten:["Type of loan","Feature"],zeilen:[["Current account credit (overdraft)","short-term credit line on the current account, revolving; expensive (debit interest, overdraft fee)"],["Long-term loan (Darlehen)","long-term sum of money, drawn only ONCE; cheaper"],["Guarantee credit (aval credit)","bank takes on liability (advance payment, retention guarantee); fee 1–3%"],["Supplier credit","customer pays later within the payment term; cost = discount not used"],["Customer credit","customer makes an advance/down payment before the service"]]},{type:"tabelle",spalten:["Loans by repayment","Meaning"],zeilen:[["Bullet loan","interest only, repayment at the end"],["Instalment loan","constant repayment amount, falling interest → instalment falls"],["Annuity loan","constant instalment (annuity = interest + repayment)"]]},{type:"formel",name:"Annual interest rate of discount",zaehler:"discount in %",nenner:"payment term − discount period",faktor:"· 360",beispiel:"3 / (30 − 8) · 360 = 49.09% p.a. → always use the discount!"},{type:"formel",name:"Interest",zaehler:"capital · interest rate · days",nenner:"36,000"}]},{titel:"Factoring, leasing, bonds, mezzanine",blocks:[{type:"begriff",term:"Factoring",erklaerung:"A company SELLS its customer receivables to a factoring bank before they are due → money earlier (minus a 0.2–1.5% fee). Open (customer knows) or silent."},{type:"begriff",term:"Leasing",erklaerung:"Medium- or long-term renting of physical goods by the owner (lessor). The lessee does NOT become the owner."},{type:"ablauf",titel:"How leasing works",schritte:[{titel:"Lessee agrees on the item with the dealer"},{titel:"Purchase contract dealer ↔ lessor, leasing contract lessor ↔ lessee"},{titel:"Dealer hands the item over to the lessee"},{titel:"Lessor pays the purchase price to the dealer"},{titel:"Lessee pays regular leasing instalments"}]},{type:"tabelle",spalten:["Type of leasing","Meaning"],zeilen:[["Operating leasing","like a rental contract, lessor does maintenance"],["Finance leasing","like loan financing, often a purchase option at the end"],["Sale and lease back","sell your own asset and lease it back → liquidity"]]},{type:"begriff",term:"Bonds",erklaerung:"Fixed-interest securities: the company raises long-term debt from many investors. Fixed term and interest; expensive, so mostly large companies."},{type:"begriff",term:"Mezzanine capital",erklaerung:'Mix of equity and debt ("mezzanine floor"): no security, long-term (≥ 5 years), profit-linked interest, no say, subordinated in bankruptcy.',beispiel:"subordinated loan, silent partnership, profit participation bond"}]}],zusammenfassung:[{titel:"Goals & types",punkte:["Financing goals: liquidity, profitability, independence (goal conflict liquidity ↔ profitability)","Internal ↔ external financing (origin) · equity ↔ debt financing (legal position)","Internal + equity: self-financing · external + equity: contributions/participation, venture capital, business angels, crowdfunding, going public, subsidies","Mixed forms: reallocation financing (internal), mezzanine capital (external)","Internal + debt: provisions · external + debt: loans, bonds"]},{titel:"Equity financing",punkte:["Self-financing open (retained profits) ↔ hidden (hidden reserves)","Crowdfunding: donation, reward, lending (debt!), equity","Reallocation: rationalisation, depreciation, selling assets","Equity ratio ≥ 20%"]},{titel:"Debt financing",punkte:["Loan security: guarantee (deficiency, ordinary, joint and several) · retention of title, cession, lien (lombard, mortgage) · credit insurance","Loan process: application → check (rating, hard/soft facts) → agreement → monitoring","Current account credit, loan (bullet, instalment, annuity), guarantee, supplier, customer credit","Annual interest of discount = discount% / (payment term − discount period) · 360","Factoring (selling receivables), leasing (renting, operating/finance, sale and lease back), bonds"]}]},"finanzplan-analyse":{schritte:[{titel:"The financial plan",blocks:[{type:"begriff",term:"Financial plan",erklaerung:"Overview of planned cash inflows and outflows and the resulting cash flow. Secures liquidity and shows financial problems early."},{type:"merke",text:"A company only stays liquid if in the long term total inflows are GREATER than total outflows."},{type:"begriff",term:"Cash flow",erklaerung:"Surplus of cash a company generates in a certain period."},{type:"text",text:"It is based on the partial plans (sales, materials, production, staff planning) and investment and financing planning."},{type:"tabelle",spalten:["Structure of the financial plan"],zeilen:[["1. Opening cash balance (cash + bank)"],["2. + planned inflows (sales, sale of assets, loans, equity)"],["3. − planned outflows (salaries, materials, energy, taxes, investments, repayments)"],["4. = surplus / shortfall (cash flow)"],["5. Balancing measures"],["6. = closing cash balance → opening balance of the next month"]]},{type:"merke",text:"Inflows and outflows ≠ income and expenses! Depreciation, for example, is an expense but not a payment."}]},{titel:"Balancing measures",blocks:[{type:"vergleich",links:{titel:"With a cash surplus",punkte:["Make profitable investments, repay loans early","Build reserves","Increase private withdrawals/profit distribution","Invest profitably in the short term","Use more discounts"]},rechts:{titel:"With a cash shortfall",punkte:["Postpone investments","Increase contributions/participations","Take out a bank loan (e.g. overdraft)","Sell assets that aren't needed","Customer credit (down payments)","Longer payment terms with suppliers"]}},{type:"vergleich",frage:"Planning period:",links:{titel:"Short-term financial plans",punkte:["up to 1 year (months, quarters)","basis for securing liquidity"]},rechts:{titel:"Long-term financial plans",punkte:["2–6 years","creditworthiness, capital structure, large investments"]}},{type:"merke",text:"Liquidity reserve: 2–3 average monthly outflows. Keep comparing target values with actual values!"}]},{titel:"Asset & capital structure",blocks:[{type:"begriff",term:"Key figures",erklaerung:"Give information about economic and financial stability – an early warning system. Basis: balance sheet and income statement."},{type:"formel",name:"Fixed asset intensity",zaehler:"fixed assets · 100",nenner:"total assets"},{type:"formel",name:"Current asset intensity",zaehler:"current assets · 100",nenner:"total assets"},{type:"merke",text:"Fixed + current asset intensity = 100%. Fixed-asset-intensive: industry, energy. Current-asset-intensive: retail, gastronomy."},{type:"formel",name:"Equity ratio",zaehler:"equity · 100",nenner:"total capital",beispiel:"≥ 20% ok · ≥ 30% very good · < 10% bad · negative = at risk of insolvency"},{type:"formel",name:"Debt ratio",zaehler:"debt · 100",nenner:"total capital"},{type:"formel",name:"Gearing (debt-to-equity ratio)",zaehler:"debt",nenner:"equity",beispiel:"E : D = 1 : 2 very good, 1 : 3 good"},{type:"formel",name:"Notional debt repayment period",zaehler:"debt − cash",nenner:"operating cash flow",beispiel:"< 3 years very good · < 5 good · > 15 at risk of insolvency"}]},{titel:"Assets & capital in relation",blocks:[{type:"merke",text:"Short-term = due within one year. Long-term assets should be financed with long-term capital!"},{type:"formel",name:"Fixed asset coverage",zaehler:"(E + long-term D) · 100",nenner:"fixed assets",beispiel:"≥ 100% = golden financing rule met"},{type:"formel",name:"Liquidity ratio 1 (cash ratio)",zaehler:"cash · 100",nenner:"short-term liabilities",beispiel:"target 20–50% (cash liquidity)"},{type:"formel",name:"Liquidity ratio 2 (quick ratio)",zaehler:"(cash + short-term receivables) · 100",nenner:"short-term liabilities",beispiel:"target 100–120%"},{type:"formel",name:"Liquidity ratio 3 (current ratio)",zaehler:"(cash + short-term receivables + stock) · 100",nenner:"short-term liabilities",beispiel:"target 150–200%"},{type:"formel",name:"Working capital",zaehler:"current assets − short-term liabilities",nenner:"1",beispiel:"should be positive"}]},{titel:"Earnings-related key figures",blocks:[{type:"tabelle",spalten:["Operating cash flow (indirect)"],zeilen:[["annual net profit / net loss"],["+ non-cash expenses (e.g. depreciation)"],["− non-cash income (e.g. release of provisions)"],["= operating cash flow"]]},{type:"formel",name:"Cash flow ratio",zaehler:"cash flow · 100",nenner:"operating performance",beispiel:"aim for ≥ 5%, ≥ 10% very good"},{type:"formel",name:"Return on equity",zaehler:"profit before tax · 100",nenner:"equity",beispiel:"good: from approx. 25% (industry), from approx. 20% (retail)"},{type:"formel",name:"Return on total capital",zaehler:"(profit before tax + interest on debt) · 100",nenner:"total capital",beispiel:"aim for ≥ 8%, > 10% good, > 15% very good"},{type:"tabelle",spalten:["Quick test","Very good","Good","Medium","Bad","At risk of insolvency"],zeilen:[["Equity ratio","> 30%","> 20%","> 10%","< 10%","negative"],["Debt repayment period","< 3 yrs","< 5 yrs","< 7 yrs","< 15 yrs","> 15 yrs"],["Cash flow ratio","> 10%","> 8%","> 5%","< 5%","negative"],["Return on total capital","> 15%","> 10%","> 8%","< 8%","negative"]]}]}],zusammenfassung:[{titel:"Financial plan",punkte:["Opening balance + inflows − outflows = cash flow → balancing measures → closing balance","Surplus: invest, reserves, repay loans, invest money · shortfall: loan, contributions, postpone investments, sell assets","Short-term (≤ 1 yr, liquidity) ↔ long-term (2–6 yrs, capital structure)"]},{titel:"Key figures",punkte:["Fixed/current asset intensity = FA or CA · 100 / total assets","Equity ratio = E · 100 / TC (≥ 20%) · debt ratio · gearing = D / E","Notional debt repayment period = (D − cash) / operating cash flow","Fixed asset coverage = (E + long-term D) · 100 / FA ≥ 100% (golden rule)","Liquidity ratio 1/2/3: target 20–50% / 100–120% / 150–200%","Working capital = CA − short-term liabilities","Operating cash flow = annual net profit + depreciation − non-cash income","Return on equity = PBT · 100 / E · return on total capital = (PBT + interest on debt) · 100 / TC"]}]},"businessplan-3jg":{schritte:[{titel:"Importance of financial planning",blocks:[{type:"begriff",term:"Financial planning in the business plan",erklaerung:"The ideas from the other parts of the business plan are shown IN NUMBERS – realistic and easy to follow. Shows whether starting the business is worth it."},{type:"merke",text:"Next to the executive summary, financial planning is the most important part of the business plan – investors and lenders check it very closely."},{type:"tabelle",spalten:["Investors pay attention to …","Meaning"],zeilen:[["Capital needed","how much, what for, where from (equity/debt)?"],["Realistic sales forecasts","based on market research and target group"],["Expected return","what does the investment bring?"],["Break-even analysis","from what quantity is the company profitable?"]]}]},{titel:"Partial plans",blocks:[{type:"text",text:"A financial plan is usually drawn up for 3–5 years and consists of these partial plans:"},{type:"kette",glieder:[{titel:"1",wert:"Sales planning"},{titel:"2",wert:"Material & staff expenses"},{titel:"3",wert:"Investment & financing"},{titel:"4",wert:"Profit & liquidity"}]},{type:"formel",name:"Planned revenue",zaehler:"net selling price · planned sales quantity",nenner:"1",beispiel:"Café: 110 customers · €4.50 · 300 days = €148,500"},{type:"begriff",term:"Gross profit",erklaerung:"Revenue minus cost of goods."},{type:"begriff",term:"Material and staff expenses",erklaerung:"Running expenses (rent, insurance, energy, advertising, wages + payroll costs, own social insurance) – projected to a full year, with an annual cost increase."},{type:"vergleich",links:{titel:"Investment planning",punkte:["All initial investments that can be capitalised","With annual depreciation (acquisition value / useful life)"]},rechts:{titel:"Financing planning",punkte:["Suitable sources of financing for the capital needed","own funds, subsidies, loans, overdraft"]}},{type:"merke",text:"Banks usually require an equity ratio of at least 20%. Go to the bank early and use grants (e.g. aws)!"}]},{titel:"Profit & liquidity planning",blocks:[{type:"vergleich",links:{titel:"Profit planning (planned income statement)",punkte:["income − expenses","= expected operating result","Accounting profit"]},rechts:{titel:"Liquidity planning",punkte:["inflows − outflows","Secures the ability to pay","Cash flow"]}},{type:"merke",text:"Profit ≠ money in the account! Loan repayments and private withdrawals = outflow, but not an expense. Depreciation = expense, but not an outflow."},{type:"tabelle",spalten:["Liquidity planning (cash flow planning)"],zeilen:[["Profit before tax"],["+ depreciation (no cash outflow)"],["− released subsidies (no cash inflow)"],["= cash flow (internal financing)"],["− investments ± loans + subsidies − income tax − private withdrawals"],["= change in liquidity"]]}]},{titel:"Break-even revenue",blocks:[{type:"begriff",term:"Break-even point (profit threshold, minimum revenue)",erklaerung:"The point at which income fully covers costs – neither profit nor loss."},{type:"formel",name:"Total contribution margin",zaehler:"revenue − variable costs",nenner:"1"},{type:"formel",name:"Contribution margin ratio",zaehler:"total contribution margin · 100",nenner:"revenue",beispiel:"96,500 / 148,500 · 100 = 64.98%"},{type:"formel",name:"Break-even revenue",zaehler:"fixed costs",nenner:"contribution margin ratio",beispiel:"86,900 / 0.6498 = €133,733.46"},{type:"merke",text:"For sole traders, a notional owner's salary (private withdrawals + income tax) counts as fixed costs. If fixed costs rise, break-even revenue rises."}]}],zusammenfassung:[{titel:"Financial planning",punkte:["Most important part of the business plan next to the executive summary","Investors: capital needed, realistic sales, return, break-even","Partial plans: sales · material/staff expenses · investment & financing · profit & liquidity","Planned revenue = net selling price · sales quantity · gross profit = revenue − cost of goods","Investment planning with depreciation; financing: equity ≥ 20%, grants"]},{titel:"Profit, liquidity, break-even",punkte:["Profit planning = income − expenses · liquidity planning = inflows − outflows","Profit ≠ liquidity (depreciation, loan repayment, private withdrawals)","Contribution margin ratio = (revenue − variable costs) · 100 / revenue","Break-even revenue = fixed costs / contribution margin ratio"]}]}},questions:{"unternehmensfuehrung-ueberblick":[{question:"According to the textbook, what does the term management mean?",options:["Only the people who run a company, but not the process of managing","Both the managers and the process of managing or running the company","Only the operational activities of employees in day-to-day business","Only the legal regulations a company must follow when running its business"],explanation:"Management refers both to the managers (people) and to the management process of managing or running a company.",correctIndex:1},{question:"Loopy is thinking about a vision for Loopy's Candy Store and the norms, values and goals that should shape her company. Which level of management does this task belong to?",options:["Operational management","Strategic management","Normative management","Lower management"],explanation:"Normative management deals with the vision and the norms, values and goals that shape a company.",correctIndex:2},{question:"Which level of management deals with the long-term planning of the company strategy?",options:["Normative management","Operational management","Operating level","Strategic management"],explanation:"Strategic management sets the long-term company strategy, while operational management takes care of putting the set goals and strategies into practice in a targeted way.",correctIndex:3},{question:"According to the textbook, which statement about the levels of hierarchy in a company is true?",options:["Every company needs at least three levels of hierarchy","The number of managers increases with each higher level","Smaller businesses often manage with one or two levels of hierarchy","Lower management has overall responsibility for the whole company"],explanation:"Smaller businesses often manage with one or two levels of hierarchy, while larger companies usually spread management tasks across three levels (top, middle and lower management).",correctIndex:2},{question:"Loopy hires a branch manager for Loopy's Candy Store who runs her branch but also acts as a link between Loopy (managing director) and the sales staff. Which management level does this position correspond to?",options:["Top management","Middle management","Operating level","Normative management"],explanation:"Middle management (e.g. head of department or branch manager) has its own management tasks and also acts as a link between top management and lower management.",correctIndex:1},{question:"Which four success factors for good communication in a company does the textbook name?",options:["Clarity, openness, regularity, empathy","Speed, control, hierarchy, digitalisation","Confidentiality, formality, distance, authority","Creativity, flexibility, competition, innovation"],explanation:"The four success factors for good communication in a company are clarity, openness, regularity and empathy.",correctIndex:0}],"normatives-management":[{question:"According to the textbook, what is a mission statement and what components does it include?",options:["Only the company's legal regulations, made up of articles, register extract and contracts","The written purpose of the company, made up of vision, mission, company philosophy and company goals","Only the company's vision, which is written regardless of mission, philosophy and goals","A pure marketing brochure made up of slogan, logo and product descriptions, with no influence on culture"],explanation:"A mission statement records in writing the purpose of the company's activities and its basic beliefs and goals. It consists of vision, mission, company philosophy and company goals and influences the corporate culture.",correctIndex:1},{question:"How is the term vision defined in connection with the mission statement?",options:["A picture of the company's long-term development that inspires and motivates","The short-term advertising slogan for a single product or campaign","The detailed description of day-to-day operations for all employees","A legally required statement to the banks on how the company is being financed"],explanation:"A vision is a picture of how a company should develop in the long term. It serves as inspiration and motivation, like a lighthouse for employees.",correctIndex:0},{question:"Loopy writes the following sentence for Loopy's Candy Store: 'We want to give children and families moments of joy with high-quality, fairly produced sweets.' Which component of the mission statement is this sentence?",options:["Vision","Company goal","Mission","Corporate culture"],explanation:"The mission describes the company's purpose and the benefit it offers customers and society. Unlike the vision, it defines the contribution the company wants to make rather than a desired picture of the future.",correctIndex:2},{question:"According to the textbook, how does a claim differ from an (advertising) slogan?",options:["A claim refers to single products, whereas a slogan refers to the whole mission in the long term","A claim is long-term and mission-related, a slogan usually short-term and product-related","Both terms mean the same, a claim is simply a shorter version of a slogan","A slogan is only used in the annual report, a claim exclusively in advertising"],explanation:"A claim is long-term and linked to the company's mission (e.g. TRAUNER Verlag's 'Education that inspires!'), while a slogan is usually short-term and refers to single products.",correctIndex:1},{question:"According to the textbook, which key questions does the company philosophy answer?",options:["How high is revenue? How many employees are there? Where is the head office?","What does the product cost? Who are the competitors? How high is the market share?","How is the company financed? What is its legal form? Who is liable?","What do we believe in? What is important to us? What do we stand for?"],explanation:"The key questions of the company philosophy are: What do we believe in? What is important to us? What do we stand for? It covers the basic values and beliefs about how people treat each other inside and outside the company.",correctIndex:3},{question:"What is meant by Corporate Social Responsibility (CSR)?",options:["Responsibility to society and the environment plus voluntary contributions to sustainability","A legal duty to pay out a share of the profits to shareholders and partners every year","A company's internal communication strategy towards all of its employees and the works council","Another word for the company vision, used only in listed corporations"],explanation:"CSR (corporate social responsibility) means companies' responsibility to society and the environment and voluntary contributions to sustainable development in social, ecological and economic areas.",correctIndex:0},{question:"What do the letters of the ESG criteria stand for?",options:["Efficiency, Structure, Governance (responsible management)","Economic, Safety, Growth","Environmental, Social, Governance (responsible management)","Environmental, Sustainability, Growth (responsible growth)"],explanation:"ESG stands for Environmental, Social and Governance (responsible management). Larger companies (from 250 employees) must report on sustainability using these criteria.",correctIndex:2},{question:"What are the Sustainable Development Goals (SDGs)?",options:["An Austrian legal standard with 17 duties for starting a company","17 global UN goals for states, companies and citizens for a sustainable future","An internal control system for the financial accounting of listed companies","A voluntary EU quality label for food that is produced regionally and sustainably"],explanation:"The SDGs are 17 global goals of the United Nations (UN) that states, companies and citizens should follow to shape a sustainable future together.",correctIndex:1},{question:"What is the UN Global Compact?",options:["A binding EU law on taxing companies according to ten ecological criteria","An international stock exchange listing that admits exclusively companies that operate sustainably","A pure marketing campaign of the United Nations without concrete principles or minimum standards","A pact between companies and the UN to voluntarily follow social and ecological minimum standards"],explanation:"The UN Global Compact is a pact between companies and the United Nations to voluntarily follow certain social and ecological minimum standards and includes ten principles on human rights, labour and the environment.",correctIndex:3},{question:"Loopy sets Loopy's Candy Store the goal of increasing customer satisfaction by 10% over the next five years. What kind of goal is this?",options:["An operational goal, because it is short-term (up to one year)","A strategic goal, because it is long-term (approx. 5 years or more)","A non-monetary goal, which therefore must not have any time reference","A goal conflict between lower management and top management in the company"],explanation:"Strategic goals have a long-term time frame (approx. 5 years or more) and turn vision and mission into strategic goals. Operational goals, on the other hand, have a short- to medium-term time frame (up to one or up to five years).",correctIndex:1},{question:"Loopy wants to introduce flexible working hours for her employees at Loopy's Candy Store. What kind of company goal is this?",options:["A monetary goal, because it causes costs and affects profit","A strategic goal in the narrow sense, because it affects all employees","A non-monetary goal, because it cannot be measured in money","A goal location in the sense of operationalising goals"],explanation:"Non-monetary goals cannot be measured in money, e.g. introducing flexible working hours. Monetary goals, on the other hand, can be measured in money, such as an increase in revenue.",correctIndex:2},{question:"What does the A in the SMART formula for writing goals stand for?",options:["Actual (up to date)","Attractive (achievable)","Automated (self-running)","Anonymised (anonymous)"],explanation:"The SMART formula stands for Specific, Measurable, Attractive (achievable), Realistic and Time-bound.",correctIndex:1},{question:"According to the textbook, which components must be included when writing operationalised goals?",options:["Only goal content, goal extent and deadline, but not who is responsible","Target group, target market, target price, target costs and target revenue","Vision, mission, company philosophy, claim and slogan","Goal content, goal extent, deadline, responsibility and goal location"],explanation:"Operationalised goals include five components: goal content (what should be achieved?), goal extent (how much?), deadline (by when?), responsibility (who is responsible?) and goal location (where?).",correctIndex:3},{question:"SONNENTOR's management wants to cut the marketing budget, while at the same time the marketing department is supposed to increase its reach on Instagram significantly. What kind of relationship between goals is this?",options:["Goal conflict (competition), because one goal hinders the other","Goal neutrality, because the two goals don't affect each other at all","Goal complementarity, because the two goals actively support each other","A form of operationalising goals using the SMART formula"],explanation:"In a goal conflict (competition), reaching one goal makes reaching another goal harder. A shrinking marketing budget usually makes a significant increase in reach harder.",correctIndex:0},{question:"How is the term corporate culture defined in the textbook?",options:["As all the company goals and key figures that have been written down","As a pure marketing tool meant to create a positive image to the outside","As what determines how people think and act, including shared, lived values","As the legal structure in which a company is organised and entered in the register"],explanation:"Corporate culture determines how people think and act in a company. It covers the values that are shared, lived and accepted within the company and shows whether the values from the mission statement are really lived.",correctIndex:2}],"strategisches-operatives-management":[{question:"According to the textbook, which order correctly describes the management process, starting from normative management?",options:["From monitoring through operational planning to the vision","From the vision through the strategy to concrete implementation","From operational planning directly to the vision","From concrete implementation through monitoring to the strategy"],explanation:"The management process leads from normative management (vision, values) through strategic management (strategy) to operational management (concrete implementation).",correctIndex:1},{question:"What do the letters of the PESTEL analysis stand for in the environment analysis?",options:["Personnel-related, purchasing-related, tax, technical, earnings-related, logistical","Pricing, earnings-related, strategic, technical, purchasing-related, logistical","Political, economic, sociocultural, technological, ecological, legal","Price, revenue, taxes, earnings, liquidity"],explanation:"The PESTEL analysis examines political, economic, sociocultural, technological, ecological and legal factors from the company's environment.",correctIndex:2},{question:"According to Michael E. Porter's five forces model, which force is NOT at the centre of the industry analysis?",options:["Bargaining power of suppliers","Availability of government funding","Threat of new competitors entering the market","Threat of substitute products"],explanation:"Porter's five forces model covers the bargaining power of suppliers and customers, the threat of new competitors and substitute products, and the rivalry among existing competitors - government funding is not part of it.",correctIndex:1},{question:"What is meant by benchmarking as part of the internal analysis?",options:["Calculating a product's relative market share compared with the strongest competitor","Comparing with best-practice companies to find room for improvement","Asking experts about a topic in several anonymous rounds","Setting a company's financial and human resources"],explanation:"In benchmarking, a company compares itself with best-practice companies to recognise its own strengths and weaknesses and room for improvement.",correctIndex:1},{question:"Loopy wants to estimate future demand for her Candy Store and uses the scenario technique for this. Which three scenarios are typically distinguished?",options:["Short-term, medium-term and long-term scenario","Internal, external and normative scenario","Positive, trend and negative scenario","Strategic, operational and normative scenario"],explanation:"In the scenario technique, starting from current data, a positive scenario (best case), a trend scenario (realistic case) and a negative scenario (worst case) are developed.",correctIndex:2},{question:"What is typical of the Delphi method as a forecasting tool?",options:["Only management makes the forecast","Experts are asked about a topic in several anonymous rounds","It is based only on mathematical models without expert opinion","It is only used to check decisions already made"],explanation:"In the Delphi method, experts from relevant fields are asked anonymously in several rounds, so their estimates usually move closer together during the process.",correctIndex:1},{question:"In a SWOT analysis, which combination is the basis for an S-O strategy (expansion strategy)?",options:["Weaknesses and threats","Strengths and threats","Weaknesses and opportunities","Strengths and opportunities"],explanation:"An S-O strategy uses the company's own strengths to consistently make the most of opportunities on the market.",correctIndex:3},{question:"Which statement about the SWOT analysis is correct?",options:["Opportunities and strengths come from the external analysis, threats and weaknesses from the internal one","Strengths and weaknesses come from the external analysis, opportunities and threats from the internal one","Opportunities and threats come from the external analysis, strengths and weaknesses from the internal one","All four elements come only from the internal analysis of the company itself"],explanation:"The SWOT analysis combines the external analysis (opportunities and threats) with the internal analysis (strengths and weaknesses) to form strategic directions.",correctIndex:2},{question:"Loopy is thinking about keeping prices in her Candy Store as low as possible to attract more customers than the competition. Which competitive strategy is she following?",options:["Product differentiation strategy","Cost leadership strategy","Niche strategy","Diversification strategy"],explanation:"The aim of the cost leadership strategy is to reach the lowest costs in the industry and so be able to offer the lowest prices.",correctIndex:1},{question:"According to the textbook, which example fits the differentiation strategy best?",options:["A discounter permanently offers goods at especially low prices","A supplier focuses on a small, special target group of customers","A luxury label like Gucci stands out through exclusivity and quality","A company opens up a completely new business area using new products"],explanation:"In the differentiation strategy, products or services stand out from the competition by being unique, as in the textbook example of Gucci.",correctIndex:2},{question:"What does a niche strategy aim at?",options:["The lowest costs in the whole industry and therefore the lowest prices","Focusing on a certain, usually small market segment","Reaching as many different target groups and segments as possible","Harvesting profits when market growth is stagnating or falling"],explanation:"In a niche strategy, a company focuses on a certain market segment or target group, as shown in the textbook with the example of Patagonia.",correctIndex:1},{question:"Which two axes make up the BCG portfolio analysis (growth-share matrix)?",options:["Absolute revenue and profit development","Relative cost advantage and market size","Relative market share and market growth","Absolute market share and industry profit"],explanation:"The BCG matrix places products into the four fields question marks, stars, cash cows and poor dogs according to relative market share and market growth.",correctIndex:2},{question:"A product is in a fast-growing market but has only a low relative market share. Which field of the BCG matrix is it in and which strategy is usually recommended?",options:["Star - growth strategy","Question mark - investment strategy","Cash cow - harvesting strategy","Poor dog - divestment strategy (withdrawal)"],explanation:"High market growth with a low relative market share marks a question mark; here an investment strategy is usually recommended to build up market share.",correctIndex:1},{question:"For Loopy's range: her own market share for fruit sweets is 12%, the strongest competitor holds 4%. What is the relative market share of this product group?",options:["0.33","8.0","3.0","1.2"],explanation:"Relative market share is your own market share divided by the market share of the strongest competitor: 12% divided by 4% gives 3.0.",correctIndex:2},{question:"Next to her Candy Store, Loopy also opens a café for a completely new target group with a new offer. Which growth strategy does this describe?",options:["Market penetration strategy","Market development strategy","Diversification strategy","Product development strategy"],explanation:"In a diversification strategy, a company opens up a completely new target group with a new product - in the textbook, e.g. with the example of a furniture store expanding into gastronomy.",correctIndex:2},{question:"What is the difference between the bottom-up and the top-down method in budgeting?",options:["In bottom-up, only management decides; in top-down, the individual departments decide alone","In bottom-up, department heads draw up partial budgets; in top-down, management sets it","In top-down there is no overall budget, only independent partial budgets of the departments","Bottom-up and top-down differ only in timing, not in who is responsible"],explanation:"In the bottom-up method, the department heads create their partial budgets, which are then combined, while in the top-down method management sets the budget and divides it into partial budgets.",correctIndex:1},{question:'Which important lesson does the textbook example of Netflix and Blockbuster show in the chapter "Making decisions"?',options:["Large companies never have to react to market changes, as their customers stay loyal","Blockbuster was the first to switch to streaming and so pushed Netflix out of the market","A timely, correct decision (switching to streaming) can decide a company's success","Decisions should be made as spontaneously as possible, without looking for information first"],explanation:"Netflix switched to streaming in time, while Blockbuster reacted too late and finally had to file for bankruptcy - the example shows how important timely, well-considered decisions are.",correctIndex:2},{question:"In which order do the phases of the PDCA cycle (Deming cycle) run?",options:["Do - Plan - Act - Check","Check - Act - Plan - Do","Plan - Do - Check - Act","Act - Check - Do - Plan"],explanation:"The PDCA cycle includes the phases Plan (set goals), Do (carry out measures), Check (check whether goals are reached) and Act (adjust measures) and is used for continuous improvement.",correctIndex:2}],"organisieren-und-fuehren":[{question:"What does a company's process organisation regulate, as opposed to its organisational structure?",options:["Only the number of employees","The company's workflows and processes","The structure and set-up of the company","The long-term vision of the company"],explanation:"While the organisational structure regulates the company's structure, the process organisation sets how the company's workflows and processes are designed.",correctIndex:1},{question:"According to the textbook, in which order is the organisational structure formed from the elements task, department and position?",options:["Position, then department, then task","Department, then task, then position","Task, then department, then position","All three elements are formed at the same time in no order"],explanation:"In the organisational structure, there are usually first tasks, which are combined into departments, within which several positions in turn take on the tasks.",correctIndex:2},{question:"What characterises a management position (line authority)?",options:["It has no decision-making or monitoring authority at all","It has the function of giving instructions, deciding and monitoring","It advises other positions without being allowed to give instructions itself","It is only responsible for its own area of work"],explanation:"Management positions such as managing directors, team leaders or project leaders have the function of giving instructions, deciding and monitoring.",correctIndex:1},{question:"Loopy hires an assistant who advises her on decisions and supports her in quality management, but is not allowed to give anyone instructions. What type of position is this?",options:["Management position","Operating position","Staff position","Line authority"],explanation:"Staff positions such as the assistant to the managing director have an advisory and supporting function, but no authority of their own to give instructions.",correctIndex:2},{question:"Which statement applies to an operating position?",options:["It can give instructions to other positions in its area","It only advises management without making decisions itself","As the top authority it monitors all other positions in the company","It decides only in its own area and cannot instruct others"],explanation:"Operating positions such as clerks or production workers decide only in their own area, without authority to give instructions to other positions.",correctIndex:3},{question:"What is typical of a high degree of centralisation in a company?",options:["Decision-making powers are spread across a large group of people","Management makes the important decisions itself","There is no management, only teams with equal rights","Each position makes its decisions completely independently"],explanation:"With high centralisation, management concentrates the important decision-making powers with one or a few people, while with decentralisation powers are passed on to a larger group of people.",correctIndex:1},{question:"What is the key feature of a single-line system?",options:["Each position has several superiors","There are no management positions","Each position reports to only one superior","All decisions are made by staff positions"],explanation:"In a single-line system each position reports to only one superior, which leads to clear chains of command and reporting.",correctIndex:2},{question:"How is the multi-line system often put into practice?",options:["As a pure single-line system without staff positions","As a matrix organisation structured by functions and divisions","Only in micro-businesses run by a single person","Only in the informal organisation of a company"],explanation:"In practice the multi-line system is usually run as a matrix organisation, in which each position is structured by two criteria at the same time - functions and divisions - and has two superiors.",correctIndex:1},{question:"Which disadvantage does the textbook attribute to the multi-line system?",options:["Communication paths that are too long across many hierarchy levels","Managers who are not busy enough","Contradicting instructions and a lot of coordination work","Lack of customer focus due to rigid department boundaries"],explanation:"Since each position in the multi-line system has several superiors, there is a risk of contradicting instructions and a lot of coordination and management work.",correctIndex:2},{question:"How is a functional organisation structured?",options:["By regions, countries or product groups (divisions)","By functions such as purchasing or production","Only by customer and target groups","By projects, each position with two superiors"],explanation:"The functional organisation structures the company in a single-line system by functional areas such as purchasing, production or sales.",correctIndex:1},{question:"How is a divisional organisation typically structured?",options:["By functions such as purchasing, production and sales","By the number of employees per department","By divisions such as regions or product groups","By functions and projects at the same time (matrix)"],explanation:"In a divisional organisation the company is structured by divisions, for example by countries, regions, product groups or customer groups.",correctIndex:2},{question:"According to the textbook, which feature does NOT belong to an agile organisation?",options:["Customer focus along the customer journey","Rigid, long-term fixed levels of hierarchy","Flat hierarchies with short decision paths","Self-organised teams with own responsibility"],explanation:"An agile organisation is characterised precisely by flat rather than rigid hierarchies, customer focus and self-organised teams so it can react flexibly to changes.",correctIndex:1},{question:"According to the textbook, which type of process does a company's personnel administration belong to?",options:["Business process","Management process","Support process","Control process"],explanation:"Support processes such as human resources or IT support the business processes, while business processes concern the core business (e.g. production, sales).",correctIndex:2},{question:"Which symbol is used for a decision in a flowchart?",options:["An oval","A rectangle","A circle","A diamond"],explanation:"In flowcharts a diamond marks a decision, while an oval stands for start/end and a rectangle for a step or process.",correctIndex:3},{question:"How does the informal organisation in a company come about?",options:["Through the structure officially set by the management","Through spontaneous needs and personal relationships","Through the organisation chart and job descriptions","Through legal rules such as labour law"],explanation:"The informal organisation comes about through employees' spontaneous needs and goals and personal, unplanned relationships - unlike the formal organisation set by management.",correctIndex:1},{question:"According to the textbook, into which three categories can leadership theories be divided?",options:["Normative, strategic and operational leadership theories","Formal, informal and agile organisation theories","Trait, behavioural and situational theories","Central, decentral and hybrid theories"],explanation:"In the textbook, leadership theories are divided into trait theories, behavioural theories and situational theories, depending on which success factor is in focus.",correctIndex:2},{question:"Which success factor is at the centre of the trait theories of leadership?",options:["The manager's behaviour depending on the situation","Certain personal traits of the manager, such as empathy","Only the manager's behaviour towards employees","The size and industry of the company"],explanation:"Trait theories assume that managers need certain personality traits such as intelligence, empathy or assertiveness to be successful.",correctIndex:1},{question:"Loopy actively involves her employees in the Candy Store in decisions and discusses new ideas together in the team. Which leadership style according to Lewin is she using?",options:["Authoritarian leadership style","Laissez-faire leadership style","Cooperative leadership style","Situational leadership style"],explanation:"In the cooperative leadership style, the manager involves employees in decisions, which encourages team spirit and initiative.",correctIndex:2},{question:"Which statement about the managerial grid is correct?",options:["It only measures a manager's intelligence and experience","It was developed by Hersey and Blanchard as a maturity model","It only distinguishes between authoritarian and cooperative leadership style","It describes leadership styles by task and people orientation"],explanation:"The managerial grid developed by Blake and Mouton describes leadership styles by task and people orientation; 9.9 (team management) is considered the most effective leadership style.",correctIndex:3},{question:"Which leadership style does Hersey and Blanchard's situational leadership model recommend for employees with a high maturity level?",options:["Telling with strict control","Delegating - without detailed explanations","Selling with strong task and people orientation","Only tough authoritarian action"],explanation:"With a high maturity level of employees - i.e. high ability and psychological maturity - the model recommends the delegating style, where tasks can be handed over without detailed explanations.",correctIndex:1},{question:"According to the Vroom-Yetton decision model, which two criteria determine leadership behaviour in decision situations?",options:["Revenue and profit","Maturity level and motivation","Decision quality and employee acceptance","Task orientation and people orientation"],explanation:"The model developed by Vroom and Yetton bases leadership behaviour on decision quality (whether the solution is technically correct) and employee acceptance of the decision.",correctIndex:2},{question:'What is characteristic of the management concept "Management by Objectives" (MbO)?',options:["Employees get no goals at all, only tasks","Only the results achieved count, no matter how they were reached","Goals and how they are checked are agreed together","Managers personally step in on every little thing"],explanation:"In management by objectives, managers and employees agree goals together and decide how reaching them will be checked.",correctIndex:2},{question:"According to the textbook, which skill is one of the leadership skills of modern managers?",options:["Only technical expertise without any contact with employees","No communication at all with the team","Digital skills to adapt processes to new technologies","Pure cost management without responsibility for staff"],explanation:"According to the textbook, the leadership skills of modern managers include digital skills that help adapt business processes and communication to new technologies.",correctIndex:2},{question:'What does the "M" in the PERMA model of positive leadership stand for?',options:["Motivation through financial incentives and bonuses","Management by Objectives","Measuring employee satisfaction regularly","Meaning - conveying the purpose of work"],explanation:'The "M" in the PERMA model stands for meaning: managers should help employees see meaning in their work so that they feel involved and take on responsibility.',correctIndex:3}],personalbedarfsplanung:[{question:"How do quantitative and qualitative staff need differ?",options:["Quantitative staff need concerns the number of employees needed, qualitative their qualifications.","Quantitative staff need concerns only managers, qualitative only apprentices.","Quantitative staff need is in the collective agreement, qualitative in the employment record.","Quantitative staff need concerns where staff are needed, qualitative when."],explanation:"Quantitative staff need states how many employees are needed; qualitative staff need describes the qualifications needed for this and is shown in the job description.",correctIndex:0},{question:"Loopy notices that she needs far more sales staff in her Candy Store before Christmas than during the rest of the year. What is the cause of the change in staff need here?",options:["A permanent drop in orders","An upcoming wave of retirements","Changes over time due to the season","A change in the collective agreement"],explanation:"According to the textbook, changes over time, such as extra seasonal demand around Christmas, are typical causes of changes in quantitative staff need.",correctIndex:2},{question:"What is a job description used for in workforce planning?",options:["It sets the legal notice period for the position.","It describes the tasks, responsibilities and powers of the position.","It replaces the employment record when someone is hired.","It is used only to calculate severance pay."],explanation:"The job description contains, among other things, the position's place in the organisation, objective, tasks/responsibilities and powers, which makes the qualitative staff need concrete.",correctIndex:1},{question:"If the current staff differs from the determined staff need, measures to cover the need are required. According to the textbook, what applies if the need is greater than the current staff?",options:["Only staff release, e.g. through dismissals, is needed.","Recruiting or staff development can be used.","Notice periods must be shortened.","Only fixed-term probation periods are allowed for new staff."],explanation:"If the need is greater than the current staff, new staff can be recruited/selected or existing staff can be qualified through staff development (e.g. retraining). If the need is smaller, staff release is needed.",correctIndex:1},{question:"According to the textbook, in which order does the recruiting and selection process run?",options:["Hiring, recruiting, requirements profile, selection procedure, analysis of documents","Requirements profile, recruiting, analysis of documents, selection procedure, hiring","Analysing application documents, requirements profile, recruiting, hiring, selection procedure","Recruiting, hiring, requirements profile, selection procedure, analysis of documents"],explanation:"The recruiting process consists of setting the requirements profile, recruiting, pre-selection (analysing application documents), selecting staff and hiring.",correctIndex:1},{question:"What is meant by the requirements profile of a position?",options:["An overview of the notice periods of all employees","The professional and personal qualifications needed for the position","A list of all voluntary social benefits of a company","The list of all applications received for a specific position"],explanation:"The requirements profile is the basis for recruiting and selecting staff and describes the professional and personal qualifications needed for the position.",correctIndex:1},{question:"Loopy is thinking about how to fill a vacant position in her Candy Store. What is the difference between internal and external recruiting?",options:["Internal recruiting is legally only allowed for management positions.","External recruiting is done only through headhunters or the AMS.","Internal recruiting uses existing staff, external recruiting outsiders.","Internal recruiting always means an assessment centre lasting several days."],explanation:"Internal recruiting covers the need with existing employees (e.g. through transfer), external recruiting with people from outside the company.",correctIndex:2},{question:'Which term describes a company from which a business usually "borrows" temporary workers for a short time?',options:["Staff leasing company","HR consultancy firm","Headhunter","Public employment service (AMS)"],explanation:'In staff leasing, a company usually "borrows" staff (temporary workers) for a short time from a staffing agency.',correctIndex:0},{question:"What is a headhunter's task in external recruiting?",options:["Registering new employees with the health insurance provider.","Directly approaching highly qualified specialists or managers.","Writing the job description for the HR management team.","Calculating the employees' severance pay."],explanation:"A headhunter is hired to approach highly qualified specialists or managers directly on behalf of a company, even if they are only passively looking for a new position.",correctIndex:1},{question:"Loopy wants her Candy Store to be seen as an attractive employer so she can find new employees more easily. Which measure is she using deliberately?",options:["Assessment centre","Protection against dismissal","Employer branding","Staff release"],explanation:"HR marketing or employer branding measures (e.g. image campaigns, benefits) are meant to create a positive employer image and win over qualified staff.",correctIndex:2},{question:"Loopy wants to publish a job ad for her Candy Store. What does the Equal Treatment Act (§ 9) require?",options:["The ad must be gender-neutral unless one gender is essential.","The ad must state a minimum age for applicants.","The ad may only be online or in newspapers for one week at most.","The ad may not include any information on salary or collective agreement."],explanation:"According to § 9 of the Equal Treatment Act, a job ad must be gender-neutral unless a certain gender is essential for the job.",correctIndex:0},{question:"According to the textbook, what is typically part of the application documents analysed in pre-selection?",options:["Employment record, severance notice and letter of notice","Only the CV in table form without any other documents","Cover letter, CV and copies of certificates","Assessment centre report and test results"],explanation:"Application documents include a cover letter, CV (with photo) and copies of certificates (school certificates and job references).",correctIndex:2},{question:"What is a job reference (Dienstzeugnis)?",options:["Confirmation of length and type of employment, often with a performance rating","A document that sets out an employee's notice period and the possible notice dates","Proof of the monthly payments into the employee provision fund","A form for registering new employees with health insurance"],explanation:"The job reference confirms the length and type of the employment and often includes a performance assessment.",correctIndex:0},{question:"According to the textbook, which statement about a good cover letter is true?",options:["It is at most one page and shows targeted interest and suitable qualifications.","It should be at least three pages long to show commitment.","It should list all previous employers in full with address and contact details.","It always replaces the CV and the copies of certificates."],explanation:"A good cover letter is no longer than one page and shows that the applicant has done their research, applied on purpose and has the right qualifications.",correctIndex:0},{question:"According to the textbook, what belongs in a CV in table form?",options:["Personal details, photo, education, work experience, skills and signature","Only the contact details of the last three employers","Only the grades from the last school or final certificate","The full wording of the future employment contract incl. salary"],explanation:"The CV in table form gives a compact overview of personal details, photo, education, work experience, skills and knowledge and, if relevant, hobbies and signature.",correctIndex:0},{question:"What should Loopy's future employee pay particular attention to when applying by email?",options:["Making the attachments as large as possible to show professionalism","Not giving a subject line","A serious email address and a file size of at most about 10 MB","Sending the documents only as Word files"],explanation:"When applying by email, applicants should use a serious email address and watch the file size (max. approx. 10 MB) so that the application doesn't end up in the spam folder.",correctIndex:2},{question:"Which risk does the textbook mention in connection with using artificial intelligence for pre-selecting applications?",options:["AI basically cannot compare application documents with the job ad.","AI trained on biased historical data can strengthen discrimination.","AI systems automatically cause higher application costs for companies.","By law, AI may generally not be used for pre-selecting applications in Austria."],explanation:"If the AI was trained with historical data in which, for example, men were systematically preferred, it can continue or strengthen this discrimination in future selections.",correctIndex:1},{question:"What is a typical feature of an assessment centre as a selection procedure?",options:["It usually only takes 15 minutes and takes place only by phone.","Several applicants are observed doing different tasks at the same time.","It consists only of a written intelligence test without personal contact.","It is used only for selecting apprentices and interns."],explanation:"In an assessment centre, several applicants are invited at the same time and observed doing tasks such as group tasks or case studies; it usually takes one to three days and is often used for management positions.",correctIndex:1},{question:"According to the proven structure shown in the textbook, in which order does a job interview typically run?",options:["End of interview, self-presentation, start of interview, questions, open conversation, company introduction","Start of interview, self-presentation, company introduction, questions, open conversation, end of interview","Questions, start of interview, open conversation, self-presentation, company introduction, end of interview","Company introduction, end of interview, start of interview, self-presentation, questions, open conversation"],explanation:"The proven structure is: start of interview, self-presentation, company introduction, questions about the CV, situational questions, open conversation, end of interview.",correctIndex:1},{question:"According to the textbook, which question would not be allowed in a job interview?",options:["Which education have you completed?","How did you deal with a difficult task in your previous job?","Are you pregnant or planning a pregnancy in the near future?","Why did you apply to our company?"],explanation:"Only questions connected with the future job are allowed. Not allowed are, among others, questions about political party or religion, pregnancy or illness.",correctIndex:2},{question:"According to the textbook, when does a company not have to issue an employment record when hiring a new employee?",options:["If it lasts at most one month or a complete written contract exists","If the agreed probation period is longer than three months","If the employee has worked in the company before","If it is a management position with Prokura (power of attorney)"],explanation:"No employment record has to be issued if the employment lasts at most one month or there is a written employment contract with all the details of the employment record.",correctIndex:0},{question:"How does the textbook define staff development (SD)?",options:["As all measures for ending employment relationships","As searching for new external staff","As all planned training and further education measures","As only legally required training for managers"],explanation:"Staff development covers all planned training and further education measures for individual professional qualification and for developing professional, methodical, social and personal skills.",correctIndex:2},{question:"According to the textbook, which goal is one of the company (not individual) goals of staff development?",options:["Increasing the employees' personal income","Developing one's own personality","Increasing personal prestige","Securing a qualified workforce"],explanation:"Company goals of SD include securing qualified staff, improving competitiveness, employee satisfaction and loyalty to the company. Individual goals, on the other hand, concern e.g. personal growth, prestige and income.",correctIndex:3},{question:"Loopy runs a structured introduction programme for her new sales assistant in which she is introduced to workflows, corporate culture and the organisational structure. What is this into-the-job measure called?",options:["Outplacement","Coaching","Quality circle","Onboarding"],explanation:"Onboarding covers measures for introducing new employees, including workflows, corporate culture and organisational structure, and is one of the into-the-job measures.",correctIndex:3},{question:"What is meant by on-the-job measures in staff development?",options:["Part-time studies outside working hours","Learning while working, e.g. instruction by managers","Talks as part of retirement preparation","Taking part in a trainee programme lasting several years before starting work"],explanation:"On-the-job measures allow learning step by step while working, mainly through instruction at the workplace by managers and, for special questions, coaching if needed.",correctIndex:1},{question:"According to the textbook, which measure is one of the near-the-job measures of staff development?",options:["An external e-learning course in the evenings lasting several weeks","Retirement preparation with talks on health in old age","Taking part in a quality circle on concrete weak points","Further education alongside regular working hours"],explanation:"Near-the-job measures such as project work, quality circles and feedback talks take place close to the workplace in terms of place, time and content.",correctIndex:2},{question:"Which statement correctly describes off-the-job measures of staff development?",options:["They are only instructions directly at the workplace by managers.","They are measures that are used only when someone leaves a job.","They are measures that only take place before the first working day.","They are learning opportunities outside the workplace, e.g. seminars."],explanation:"Off-the-job measures are learning opportunities outside the workplace, e.g. e-learning, training/seminars/workshops or further education alongside work.",correctIndex:3},{question:"According to the textbook, which two types of measures are out-of-the-job measures of staff development?",options:["Onboarding and trainee programme","Coaching and instruction at the workplace","Feedback talks and quality circles","Retirement preparation and outplacement"],explanation:"Out-of-the-job measures make leaving an employment easier: retirement preparation supports the transition into retirement, outplacement measures support professional reorientation after being given notice.",correctIndex:3},{question:"According to the textbook, which way of ending an employment relationship is only possible for permanent employment?",options:["Expiry according to the employment contract","Ending during the agreed probation period","Notice (termination)","Automatic change into a permanent employment"],explanation:"Notice is only possible for permanent employment; expiry and ending during the probation period concern fixed-term employment.",correctIndex:2},{question:"According to the textbook, how long can a probation period usually be agreed at most - and what is the exception?",options:["At most three months, exception: apprentices have a one-month probation period","At most one year, exception: apprentices have no probation period","At most two weeks with no exceptions","At most one month, exception: apprentices have a three-month probation period"],explanation:"A probation period can be agreed for at most one month; apprentices have a three-month probation period.",correctIndex:3},{question:"Loopy's sales assistant wants to resign. According to the textbook, on which date can she generally do this and how long is the notice period?",options:["Only at the end of a calendar quarter, notice: 3 months","Only on the 15th of a month, notice: 6 weeks","Any time without notice","On the last day of any month, notice: usually one month"],explanation:"Notice by the employee can be given for the last day of any month; the notice period is usually one month.",correctIndex:3},{question:"Loopy wants to give notice to an employee who has worked in her Candy Store for 8 years. According to the scale shown in the textbook, which notice period must she keep to as the employer?",options:["6 weeks","2 months","3 months","5 months"],explanation:"For employment in the 6th to 15th year, the employer's notice period according to the scale shown in the textbook is 3 months.",correctIndex:2},{question:"According to the textbook, on which date can salaried employees usually be given notice by the employer, unless the collective agreement says otherwise?",options:["On any day of the month","Only on the first day of each month","Only once a year at the end of the calendar year","Only at the end of a calendar quarter"],explanation:"Usually salaried employees can only be given notice by the company for the end of a calendar quarter; however, a collective agreement can also set every 15th or last day of the month as the termination date.",correctIndex:3},{question:"According to the textbook, which group of people enjoys special protection against dismissal?",options:["All employees who have been with the company for less than a year","All part-time employees","All employees over 50","Expectant mothers and people on parental leave"],explanation:"Special protection against dismissal applies to, among others, expectant mothers, people on parental leave, people doing military or civilian service, works council members and people with recognised disabilities.",correctIndex:3},{question:"According to the textbook, how do dismissal and resignation without notice (Austritt) differ?",options:["Dismissal is declared by the employer, resignation without notice by the employee, both immediately.","Dismissal and resignation without notice are exactly the same, only named differently.","A dismissal is always by mutual agreement, a resignation without notice never.","With a resignation without notice the full notice period must be kept, with a dismissal not."],explanation:"A dismissal is given immediately by the employer for serious misconduct by the employee (e.g. violence); a resignation without notice is declared immediately by the employee for serious misconduct by the employer (e.g. withholding pay).",correctIndex:0},{question:"According to the textbook, what are job-search days that employees are entitled to when the company gives notice?",options:["An extra month's salary paid after the employment has ended","Compulsory unpaid leave in the final weeks before the last working day","A one-off bonus for especially long service","Paid time off of one fifth of weekly working hours for job hunting"],explanation:"When the company gives notice, employees are entitled to paid time off amounting to one fifth of weekly working hours to look for a new job. If they resign themselves, there is usually no entitlement.",correctIndex:3},{question:'According to the textbook, how does the "new severance pay" through the employee provision fund (MVK) work?',options:["The employer continuously pays 1.53% of gross pay into an MVK.","Severance pay is only paid out in case of dismissal, never in case of termination by mutual agreement.","The employee pays a fixed amount into the MVK every month.","Severance pay is cancelled completely for fixed-term employment."],explanation:"For every employee the employer continuously pays 1.53% of gross pay into an MVK; after at least three years of payments the employee can choose between payout or taking it to the next employer.",correctIndex:0}],personaleinsatzgestaltung:[{question:"In the hierarchy of the legal system, the collective agreement is above the individual employment contract. When may an individual employment contract still differ from the rules of the collective agreement?",options:["If management and the works council both agree to the difference in writing","If the works council agrees to it in a works agreement","If it is better for the employees (favourability principle)","If the different rule only applies for a limited number of months"],explanation:"Lower-ranking rules may only differ from higher-ranking ones if the difference is more favourable for employees – this is called the favourability principle.",correctIndex:2},{question:"An employee of Loopy's Candy Store passes on the secret recipe for the homemade caramel sweets to a friend who wants to open a competing shop. Which duty is he breaking?",options:["Duty of equal treatment (non-discrimination)","Duty of care (protecting life and health)","Duty of special protection","Duty of loyalty (confidentiality)"],explanation:"Employees have a duty of loyalty, which includes, among other things, keeping trade secrets confidential.",correctIndex:3},{question:"What are the legal normal working hours in Austria?",options:["12 hours per day / 60 hours per week","8 hours per day / 40 hours per week","10 hours per day / 50 hours per week","6 hours per day / 35 hours per week"],explanation:"The law sets normal working hours of eight hours per day or 40 hours per week; many collective agreements set shorter working hours.",correctIndex:1},{question:"Loopy wants to extend the opening hours of Loopy's Candy Store before Christmas and ask her employees to work more overtime. What maximum may working hours including overtime not exceed?",options:["12 hours per day / 60 hours per week","14 hours per day / 70 hours per week","10 hours per day / 50 hours per week","8 hours per day / 40 hours per week"],explanation:"Including overtime, working hours may not exceed twelve hours per day and 60 hours per week (with special rules for certain occupations).",correctIndex:0},{question:"By law, from how many daily working hours must at least one rest break be taken, and how long must it be at least?",options:["more than 4 hours, at least 15 minutes","more than 8 hours, at least 60 minutes","more than 6 hours, at least 30 minutes","more than 10 hours, at least 45 minutes"],explanation:"If daily working hours are more than six hours, a rest break of at least 30 minutes must be given.",correctIndex:2},{question:"Which extra pay are employees entitled to if overtime is paid out instead of being compensated with time off?",options:["20% or 40%","30% or 75%","25% or 50%","50% or 100%"],explanation:"Overtime paid out earns extra pay of 50% or 100% (e.g. for night, public holiday and Sunday work). Alternatively, overtime can be compensated with time off.",correctIndex:3},{question:"An employee of Loopy's Candy Store has worked in the business for 27 years on a five-day week. By law, how many working days of holiday is she entitled to at least?",options:["25 working days","30 working days","36 working days","20 working days"],explanation:"Generally, on a five-day week there are 25 working days of holiday; from the 26th working year the entitlement rises to 30 working days.",correctIndex:1},{question:"Loopy's Candy Store has a flexitime agreement with core working hours from 9:00 to 15:00. What does this mean for the employees?",options:["Everyone must be present during core hours; otherwise working hours are flexible","They may only work from 9 to 15 and must leave the shop straight afterwards","Core working hours replace the legal normal working hours of 40 hours a week","Core working hours only apply to part-time staff, while full-time staff work flexibly"],explanation:"Flexitime allows weekly working hours to be arranged flexibly, but all employees must be present during the agreed core working hours.",correctIndex:0},{question:"According to the Maternity Protection Act, for how long before and after the birth is there a complete ban on employment for female employees?",options:["2 weeks before and 2 weeks after the birth","4 weeks before and 4 weeks after the birth","8 weeks before and 8 weeks after the birth","12 weeks before and 12 weeks after the birth"],explanation:"For working women there is a complete ban on employment eight weeks before and eight weeks after the birth, which cannot be changed even by agreement.",correctIndex:2},{question:"What partly makes up for the loss of income during parental leave?",options:["Maternity pay from the Austrian Health Insurance Fund","Childcare benefit from the state","The employer continuing to pay the full salary","Overtime pay"],explanation:"During parental leave no wages or salary are paid; to partly make up for the loss of income, the state pays childcare benefit (maternity pay, on the other hand, is paid during maternity protection).",correctIndex:1},{question:"From how many permanently employed employees over 18 does a business have the right to a works council?",options:["5 employees","10 employees","20 employees","3 employees"],explanation:"The right to a works council exists in businesses that permanently employ at least five employees over 18.",correctIndex:0},{question:"Which level is at the very top of Maslow's hierarchy of needs?",options:["Basic needs","Safety needs","Need for esteem and recognition","Need for self-actualisation"],explanation:"Maslow's hierarchy of needs goes from basic needs at the base to the need for self-actualisation at the top.",correctIndex:3},{question:"According to Herzberg's two-factor theory, salary is a hygiene factor. What does this mean?",options:["A good salary motivates strongly in the long term and replaces other incentives","Too little pay causes dissatisfaction, but good pay alone does not keep people satisfied","Salary is one of the intrinsic motivators, like recognition and responsibility","Hygiene factors only concern the content of the work itself, never the salary"],explanation:"Hygiene factors such as salary prevent dissatisfaction when they are missing, but on their own they don't create lasting satisfaction or motivation – that is what motivators do.",correctIndex:1},{question:"Loopy regularly has her sales staff at Loopy's Candy Store switch between the till, stocking shelves and making chocolates to avoid monotony. Which workplace design measure is this?",options:["Job enrichment","Job enlargement","Job rotation","Cafeteria system"],explanation:"The systematic change of workplace within a company to counteract monotonous tasks is called job rotation.",correctIndex:2},{question:"Harvest helpers who pick strawberries for the fruit sweets of Loopy's Candy Store in summer are paid per kilogram picked. Which form of pay is this?",options:["Time wage","Bonus wage","Piece-rate wage","Profit sharing"],explanation:"With piece-rate pay (here per unit), pay is linked to the amount produced, e.g. the number of kilos of strawberries picked.",correctIndex:2}],personalbeurteilung:[{question:"In which form of staff appraisal is feedback gathered from colleagues, managers and the person being assessed to get as complete a picture as possible?",options:["Self-assessment","Rating method","Goal-agreement method","360° feedback"],explanation:"360° feedback gathers feedback from the whole working environment (colleagues, managers, self-assessment) and so gives an especially meaningful picture.",correctIndex:3},{question:"In which staff appraisal method is it checked whether previously agreed goals were reached?",options:["Rating method with behaviour description","Goal-agreement method","Appraisal by colleagues","360° feedback"],explanation:"In the goal-agreement method it is checked whether the jointly agreed goals were reached; it focuses only on actual work performance.",correctIndex:1},{question:"A branch manager of Loopy's Candy Store is extremely charming and articulate in sales talks. Her manager therefore rates her across the board as an excellent employee, even though her till reports often contain mistakes. Which appraisal error is this?",options:["Recency effect","Selective perception","Halo effect","Similarity effect"],explanation:"With the halo effect, a single, especially striking trait (here: being articulate) outshines the whole appraisal, even though the professional performance is weaker.",correctIndex:2},{question:"An employee works especially hard in the last two weeks before his annual appraisal, although he performed rather averagely for the rest of the year. His manager still rates him as very good. Which appraisal error occurs here?",options:["Halo effect","Recency effect","Similarity effect","Selective perception"],explanation:"With the recency effect, the most recent performance is given more weight in the appraisal than performance over the whole year.",correctIndex:1},{question:"A manager thinks a new employee is unreliable from the start and since then has mainly paid attention to his mistakes, while overlooking positive performance. Which appraisal error describes this behaviour?",options:["Similarity effect (similar-to-me effect)","Halo effect","Recency effect","Selective perception"],explanation:"With selective perception, people mainly notice information that matches their existing opinion or expectation.",correctIndex:3},{question:"A manager rates an applicant more positively because she has the same hobbies and a similar lifestyle as the manager – regardless of her actual performance. What is this appraisal error called?",options:["Similarity effect","Recency effect","Halo effect","Selective perception"],explanation:"With the similarity effect, people rate others more positively when they are similar to themselves (e.g. in age, hobbies or values), often without realising it.",correctIndex:0},{question:"Which of the following methods is one of the qualitative methods of HR controlling?",options:["Employee surveys and talks","Staff costs per hour","Staff turnover rate","Number of applicants per position"],explanation:"Qualitative methods capture aspects that are hard to measure, such as corporate culture or motivation, e.g. through staff appraisals, employee surveys and talks, potential analyses and strengths-weaknesses analyses.",correctIndex:0},{question:"How is the key figure staff intensity calculated?",options:["Staff costs divided by the number of employees","Operating performance divided by staff costs","Staff costs times 100 divided by operating performance","Revenue times 100 divided by staff costs"],explanation:"Staff intensity is calculated as staff costs x 100 / operating performance and shows what percentage of operating performance is spent on staff costs.",correctIndex:2},{question:"What does the key figure EBITDA used in HR controlling stand for?",options:["Earnings before interest, taxes, depreciation and amortization","Employee Benefits including Training, Development and Allowances","European Business Index for Trade and Administration","Effective Business Income Tax Deduction Amount"],explanation:'EBITDA stands for "Earnings before interest, taxes, depreciation and amortization" and describes the result before interest, taxes and depreciation.',correctIndex:0},{question:"Loopy has to submit the monthly payroll tax return for her employees to the tax office. Which task of personnel administration is this?",options:["Payroll task","Reporting task","Monitoring task","HR controlling"],explanation:"Reporting tasks include internal reports (e.g. anniversaries) and external reports such as the payroll tax return to the tax office.",correctIndex:1},{question:"According to the model shown in the textbook, what is the main difference between employer branding and HR marketing?",options:["Employer branding builds the employer brand long term, HR marketing puts it into practice","Employer branding is aimed only at managers, HR marketing only at apprentices and pupils","Employer branding is a legal duty, HR marketing is a voluntary extra service","HR marketing builds the employer brand long term, employer branding puts it into practice"],explanation:"Employer branding covers all measures for building an attractive employer brand in the long term; HR marketing is putting this brand into practice through concrete measures such as careers websites or recruiting events.",correctIndex:0},{question:"According to the textbook, on which type of platform can potential applicants find out about the experiences of current and former employees of a company (e.g. kununu)?",options:["Online job board for vacancies","Employer rating platform","Collective agreement","HR controlling tool"],explanation:"On employer rating platforms like kununu, people can find out how current and former employees rate areas such as pay, benefits or work-life balance.",correctIndex:1}],produktionsbetriebe:[{question:"What are companies from industry and trades that make physical goods called?",options:["Production businesses","Trading businesses","Service businesses","Investment businesses"],explanation:"Companies from industry and trades that make physical goods are called production businesses or manufacturing businesses.",correctIndex:0},{question:"According to the textbook, which areas of the economy belong to the production sector (secondary sector)?",options:["Only industry, without trades or construction","Industry, trades and construction","Commerce, trades and transport","Agriculture, forestry and fishing"],explanation:"The production sector (secondary sector) includes all companies that make products (industry and trades) as well as construction.",correctIndex:1},{question:"Loopy is interested in the economic importance of the secondary sector in Austria. According to the textbook, what share of gross domestic product is generated in the secondary sector?",options:["About 71%","Slightly more than 1%","About 28%","About 50%"],explanation:"In Austria about 28% of gross domestic product is generated in the secondary sector, about 71% in the tertiary sector and slightly more than 1% in the primary sector.",correctIndex:2},{question:"According to the textbook, how has the share of employees in the secondary sector in Austria developed in recent decades?",options:["It has risen sharply and is now over 50%","It has stayed constant at about 71% for decades","It has fallen sharply and is now below 5%","It has fallen steadily and is now about 25%"],explanation:"The share of employees in the secondary sector has fallen steadily in recent decades and is currently about 25%.",correctIndex:3},{question:"According to the textbook, roughly how many production businesses are there in Austria, and what share of them are small and medium-sized businesses?",options:["About 80,000 businesses, of which over 95%","About 8,000 businesses, of which about 50%","About 800,000 businesses, of which only 10%","About 20,000 businesses, of which roughly 70%"],explanation:"There are more than 80,000 production businesses in Austria, over 95% of which are small and medium-sized businesses.",correctIndex:0},{question:"According to the textbook, what share of Austrian exports comes from the production sector?",options:["About 30%","About 70%","About 50%","About 90%"],explanation:"About 70% of Austrian exports come from the production sector.",correctIndex:1},{question:"Loopy reads in the textbook that Austria has recently become less attractive as an industrial location. Which reasons are given, among others?",options:["Energy costs that are too low and a tax burden that is too low","Falling labour costs, less bureaucracy and an oversupply of skilled workers","Higher labour and energy costs, bureaucracy, tax burden and a skills shortage","Too many available workers and wages in industry that are too low"],explanation:"The textbook names, among other things, higher labour and energy costs, a lot of bureaucracy, the tax burden and a shortage of qualified workers.",correctIndex:2},{question:"According to the textbook, by which two criteria are production businesses mainly divided?",options:["Type of legal form and size of the company","Type of location and type of ownership structure","Level of revenue and number of employees","Type of customer and type of industry/activity"],explanation:"Production businesses can be divided, among other things, by type of customer and by type of industry/activity.",correctIndex:3},{question:"Loopy's Candy Store makes sweets for end consumers, but also buys a filling machine from another company. What are the two types of business involved correctly called?",options:["Loopy's Candy Store is a consumer goods business, the machine manufacturer a capital goods business","Loopy's Candy Store is a capital goods business, the machine manufacturer a consumer goods business","Both are consumer goods businesses","Both are capital goods businesses"],explanation:"Consumer goods businesses make physical goods for end users; capital goods businesses make physical goods for other companies, e.g. machines and equipment.",correctIndex:0},{question:"According to the textbook, which feature typically distinguishes an industrial business from a trade business?",options:["Industrial businesses have a lower degree of automation and are labour-intensive","Industrial businesses use more fixed assets and have high fixed costs","Industrial businesses are usually run personally by the owner","Industrial businesses are always small businesses"],explanation:"Industrial businesses are characterised, among other things, by more use of fixed assets, high fixed costs and a higher degree of automation; trade businesses tend to use more materials and labour and are often run by the owner.",correctIndex:1},{question:"According to the textbook, which four goals do production businesses typically pursue in their production?",options:["High stock levels, many locations, high advertising spending and the largest possible workforce","Only maximising profit at any price, even at the expense of the environment and customers","Optimal factor use, customer satisfaction, low costs, sustainable and ethical production","Maximum revenue, as many product variants as possible, high capacity use and rapid growth"],explanation:"The textbook names as goals of company production the optimal use of the factors of production, customer satisfaction, low production costs and sustainable and ethical production.",correctIndex:2},{question:"According to the textbook, with which three key figures can the optimal use of the factors of production be checked?",options:["Liquidity, equity ratio and debt-to-equity ratio","Market share, revenue growth and contribution margin","Lead time, set-up time and capacity utilisation","Productivity, efficiency and profitability"],explanation:"The optimal use of the factors of production can be checked with the three key figures productivity, efficiency and profitability.",correctIndex:3},{question:'How does the textbook define the "location" of a business?',options:["The geographic place where a business is active","The legal form under which a company carries out its business","The total number of people a company employs","The brand name under which a company trades"],explanation:"The location of a business is the geographic place where its activities are carried out; depending on the activity, a distinction is made e.g. between production, research, administration and sales locations.",correctIndex:0},{question:"Which three types of location factors does the textbook distinguish?",options:["Local, regional, national and international location factors","Procurement-, production- and sales-related location factors","Tax-related, employment-law and socio-political location factors","Short-term, medium-term and long-term location factors"],explanation:"The textbook distinguishes procurement-related, production-related and sales-oriented location factors.",correctIndex:1},{question:"According to the textbook, voestalpine is investing €70 million in expanding its site in Jeffersonville (USA). Which principle is the company following?",options:["Just-in-time principle","Make-to-stock principle","Follow-the-customer principle","Business excellence principle"],explanation:'By expanding its site in strategically important markets like the USA, voestalpine continues its "follow-the-customer principle" to supply customers there faster and more efficiently.',correctIndex:2}],"leistungserstellungsprozess-produktion":[{question:"According to the textbook, what happens in a company's production?",options:["Labour, equipment and materials are combined to make products","Finished products are packed, stored and delivered to the customers","Raw materials are bought and the funds for new machines are provided","Advertising for new products is planned and sales are organised"],explanation:"In production, the factors of production labour, equipment and materials are combined so that products are made.",correctIndex:0},{question:'How does the textbook define the term "process"?',options:["Another word for the capacity of a machine or plant","A sequence of connected activities that follow one another in time","A one-off, isolated activity with no link to other activities","A collection of any activities in a business that are independent of each other"],explanation:"A process is defined as a sequence made up of connected activities that follow one another in time.",correctIndex:1},{question:"According to the textbook, what is meant by product innovation?",options:["Reducing the product range to one single product that is particularly successful","An existing product is sold unchanged under a new name","A completely new product is created or an existing one is developed further","An existing product is sold abroad for the first time"],explanation:"In product innovation, a completely new product is created or an existing product is developed further.",correctIndex:2},{question:"According to the textbook, in which three phases does the innovation process usually run?",options:["Market analysis, advertising campaign (promotion), launch of the new product","Purchasing, storage of materials, delivery to customers","Production (manufacturing), quality control, sale to customers","Product proposal, development (design), preparing production"],explanation:"The innovation process usually runs in the phases product proposal, development (design) and preparing production, accompanied by ongoing cost controlling.",correctIndex:3},{question:"More and more customers of Loopy's Candy Store are asking for sugar-free sweets, so Loopy develops a new range. Which innovation strategy describes this approach?",options:["Market pull strategy","Technology push strategy","Simultaneous engineering","Business excellence strategy"],explanation:"In the market pull strategy, unmet customer wishes or new trends on the market trigger innovative products.",correctIndex:0},{question:"Which example does the textbook give for the technology push strategy?",options:["Customers' growing interest in vegan food and plant-based products","Customers' wish for furniture that is individually designed and sustainable","Rising demand for lower prices in retail","Artificial intelligence, which led to virtual assistants and chatbots"],explanation:"In the technology push strategy, new technologies trigger innovative products, as the textbook shows with the example of artificial intelligence.",correctIndex:3},{question:"According to the textbook, what is a graphic tree diagram called that shows how a product is built from assemblies and individual parts?",options:["Bill of materials","Capacity profile","Product structure","Technical drawing"],explanation:"The product structure uses a graphic tree to show how the product is built up.",correctIndex:2},{question:"According to the textbook, what is a bill of materials?",options:["A graphic tree diagram of the product showing assemblies and individual parts","A list of all work steps, including the processing time per item","A target/actual comparison of development costs","A list of all assemblies and individual parts, including quantities"],explanation:"Based on the technical drawing or product structure, the bill of materials is created: a list of all assemblies and individual parts including quantities.",correctIndex:3},{question:"According to the textbook, what is the parallel development of products and manufacturing processes called, which shortens development time?",options:["Buying in","Fixed cost degression","Simultaneous engineering","Backward scheduling"],explanation:"The parallel development of products and manufacturing processes is called simultaneous engineering and shortens development time and the time to market.",correctIndex:2},{question:"A car manufacturer calculates development costs of €1.5 billion for a new model with expected sales of 1 million cars (€1,500 per car). If only 100,000 cars are sold instead, the costs rise to €15,000 per car. According to the textbook, which effect does this example show?",options:["Economies of scale","Fixed cost degression","Market saturation","Backward scheduling"],explanation:"With lower sales, the fixed costs per unit rise sharply – this shows the effect of fixed cost degression, i.e. fixed costs per unit falling as production quantity rises.",correctIndex:1},{question:"According to the textbook, what is set in sales planning, and what is the planned sales quantity called?",options:["Which products can probably be sold in which quantity; this quantity is called primary demand","Which materials must be bought in which quantity; this quantity is called net requirement","Which products are in stock in which quantity; this quantity is called gross requirement","Which products can probably be sold in which quantity; this quantity is called secondary demand"],explanation:"In sales planning it is estimated which products can probably be sold in which quantity. This planned sales quantity is called primary demand.",correctIndex:0},{question:"According to the textbook, which three decisions are made in production programme planning?",options:["Location, legal form and capital structure","Type of products, quantity of products and timing","Size of the advertising budget, choice of sales channel and pricing","Choice of suppliers, payment terms and discounts"],explanation:"In production programme planning, the type of products, the quantity of products and the timing of production are set.",correctIndex:1},{question:"Loopy's Candy Store only produces individually designed gift boxes when a customer actually orders, while the standard sweets are made in stock for sale in the shop. What are these two types of production programme planning called?",options:["Both are make to stock","Gift boxes: make to stock; standard sweets: make to order","Gift boxes: make to order; standard sweets: make to stock","Both are make to order"],explanation:"With make to order, production only takes place once there is a customer order; with make to stock, products are made in stock based on forecast sales so the company can always deliver.",correctIndex:2},{question:"According to the textbook, when is the optimal production programme reached?",options:["When as many different products as possible are made at the same time and all capacity is fully used","When stock levels are maximised so that the company can always deliver","When capacity is fully used and as much as possible is produced for stock","When the contribution margin is maximised and capacity is used, but no more is produced than can be sold"],explanation:"Companies try to create an optimal production programme that maximises the contribution margin or profit, with capacity being used but without producing more than can be sold.",correctIndex:3},{question:"A carpentry business produces 100 tables to order and 20 tables for stock. 1 table needs 4 table-leg brackets (so the gross requirement is 480 pieces); 95 table-leg brackets are already in stock. According to the textbook, what is the net requirement for table-leg brackets?",options:["480 pieces","95 pieces","385 pieces","575 pieces"],explanation:"The net requirement is the gross requirement minus stock: 480 - 95 = 385 table-leg brackets.",correctIndex:2},{question:"According to the textbook, how do lead time scheduling and capacity scheduling differ?",options:["Capacity scheduling follows the order of work steps; lead time scheduling also takes the available capacity into account","The two methods are identical and only differ in name","Both methods only take customer wishes and delivery dates into account","Lead time scheduling follows the order of work steps; capacity scheduling also takes the available capacity into account"],explanation:"In lead time scheduling, the order of work steps is based on the order of the tasks to be done; capacity scheduling also takes into account how busy the available capacity is.",correctIndex:3},{question:"According to the textbook, which two parts make up lead time?",options:["Processing time (set-up and operation time) and transition time (idle and transport time)","Purchasing time (ordering and delivery time) and sales time (selling and shipping time)","Set-up time (preparing the machines) and operation time (actual manufacturing)","Planning time (design and review time) and monitoring time (measuring and testing time)"],explanation:"Lead time is made up of processing time (set-up time + operation time) and transition time (idle time + transport time).",correctIndex:0},{question:"According to the textbook, what disadvantage does backward scheduling have compared with forward scheduling?",options:["Higher storage costs because products are finished early","Lead times that are too long because of large time buffers","Small time buffers between end date and delivery date","More capital tied up because materials are bought early"],explanation:"In backward scheduling, you calculate back from the delivery date to find when production must start at the latest; the disadvantage is small time buffers between end date and delivery date, the advantage is lower storage costs.",correctIndex:2},{question:"Which example does the textbook give for single-unit production?",options:["Bottling mineral water","Making TV sets on an assembly line","Producing a certain car series","Building a cruise ship"],explanation:"As an example of single-unit production, the textbook names building a cruise ship, where a single item is made to order with exact specifications.",correctIndex:3},{question:"According to the textbook, what is a typical feature of mass production?",options:["Producing a single item to exact customer specifications, e.g. a cruise ship","Producing identical products in any quantity at low production cost","Production that only takes place at the site, e.g. building a bridge","Producing a limited number of products defined exactly in advance, e.g. a car series"],explanation:"In mass production, identical products are made in any quantity at low production cost and with fast lead times thanks to automation, e.g. bottling mineral water.",correctIndex:1},{question:"According to the textbook, what is a typical feature of workshop production?",options:["All workstations are connected by an automated transport system","The manufacturing equipment is transported to the site, e.g. a building site","Similar tasks are done in separate workshops within the company","Work on the assembly line becomes monotonous because the same movements are repeated"],explanation:"In workshop production, similar tasks are done in workshops within the company, as the textbook shows with the example of a metal fence.",correctIndex:2},{question:"How does the textbook describe production controlling?",options:["As a department responsible only for selling the finished products","As a one-off final inspection that takes place only after all production is finished and sorts out faults","As a pure accounting function that only records production costs at the end of the year","As a separate process alongside production that analyses deviations and room for improvement"],explanation:"Production controlling is a separate process that runs alongside actual production and analyses it for deviations or room for improvement.",correctIndex:3},{question:"At Glanzer Cosmetics GmbH the target lead time of a new filling machine is 5 minutes per item. In the first test run, however, 6 minutes 30 seconds are measured. According to the textbook, what does the new test run after the corrective measures show?",options:["Exactly 5 minutes","6 minutes 10 seconds","5 minutes 20 seconds","4 minutes 50 seconds"],explanation:"After the corrective measures (reducing idle times, adjusting the target), the new test run shows a lead time of 5 minutes 20 seconds.",correctIndex:2},{question:"According to the textbook, what is at the centre of quality management?",options:["Customer focus: products and processes are designed to meet customers' requirements","Cost focus: products and processes are designed to keep manufacturing costs as low as possible","Technology focus: products are based on what is technically possible","Only checking finished products at the end of production"],explanation:"Customer focus is at the centre of quality management: products and processes are designed to meet customers' requirements and wishes.",correctIndex:0},{question:"How does the textbook describe the interaction between customer-oriented and technical quality?",options:["Only technical quality, i.e. measurable product features, matters for a product's success","Customer-oriented and technical quality exclude each other","Only customer-oriented quality is covered in the textbook","Both must be fulfilled and together form the basis for a good product"],explanation:"Customer-oriented quality (customers' wishes and expectations) and technical quality (objective, measurable product features) must both be fulfilled and together form the basis for a good product.",correctIndex:3},{question:"Which three quality areas does the textbook name using the example of Glanzer Cosmetics GmbH?",options:["Marketing quality, staff quality and financial quality","Location and supplier quality, logistics quality and system quality","Product quality, price quality and packaging quality","Product and service quality, process quality and system quality"],explanation:"The quality areas include product and service quality, process quality and system quality.",correctIndex:3},{question:"In October 2024 Coca-Cola had to recall 28 million bottles of Coca-Cola and Fanta in Austria because small pieces of metal could get into the drinks through a faulty sieve. According to the textbook, which consequence of poor quality does this example show?",options:["Rising profit","Higher customer satisfaction","Falling material costs","Product recall"],explanation:"Poor quality can lead, among other things, to product recalls, damage to the company's image and falling sales, revenue and profit, as the Coca-Cola example shows.",correctIndex:3},{question:"Which four stages of development of quality management does the textbook name?",options:["Quality control, quality assurance, total quality management and business excellence","Quality planning, quality steering, quality inspection and continuous quality improvement","Quality control, ISO 9001 certification, lean management and Six Sigma","Only a single stage that has applied unchanged since the 1950s"],explanation:"With industrial mass production, the stages quality control, quality assurance, total quality management and finally business excellence developed.",correctIndex:0}],"investition-finanzierung-ueberblick":[{question:"According to the textbook, what does a company's financial planning provide?",options:["It is used only for preparing the annual financial statements, i.e. balance sheet and income statement","It only shows past cash flows without estimating future capital needs","It provides an overview of current and future capital needs and financing options","It replaces the need for a balance sheet"],explanation:"According to the textbook, financial planning provides an overview of current and future capital needs and financing options and is therefore the basis for using financial resources efficiently for investments.",correctIndex:2},{question:"At which management levels does a company's financial planning take place?",options:["At all management levels, from normative to operational management","Only at the strategic level, as it always concerns long-term budgets","Only at the operational level, as it only concerns ongoing cost control","Only at the normative and strategic levels, not in operational management"],explanation:"Financial planning is used at all management levels: in normative management long-term financial goals are set, in strategic management budgets are planned, and in operational management there is ongoing cost control.",correctIndex:0},{question:"A company plans how to secure liquidity for salaries and supplier invoices. According to the textbook example, which management level does this financial planning belong to?",options:["Normative management, because it is about long-term goals","Strategic management, because it is about planning the annual budget","No management level, because salaries are not part of financial planning","Operational management, because it is about ongoing cost control"],explanation:"The textbook gives exactly this case as an example of operational financial planning: planning finances to secure liquidity for salaries, supplier invoices etc.",correctIndex:3},{question:"A company assigns multi-year financing to a planned investment in new technologies to reduce CO2. According to the textbook example, which type of financial planning is this?",options:["Operational financial planning","Strategic financial planning","Normative financial planning","Short-term liquidity planning"],explanation:"As an example of strategic financial planning, the textbook names planning the finances of an investment in new technologies to reduce CO2, because a long-term financing decision is made here.",correctIndex:1},{question:"According to the textbook, how are investment and financing connected in a company's balance sheet?",options:["Investment concerns the liabilities side (source of funds), financing the assets side (use of funds)","Investment and financing are completely independent of each other in the balance sheet","Investment concerns the assets side (use of funds), financing the liabilities side (source of funds)","Only financing affects the balance sheet, investment does not"],explanation:"An investment shows up on the assets side of the balance sheet (assets = use of funds), while the liabilities side shows how these assets were financed (capital = source of funds). Investment and financing are therefore closely linked through the balance sheet equation.",correctIndex:2}],investitionsmanagement:[{question:'How is the term "investment" defined in investment management?',options:["Using financial resources to acquire assets","Raising financial resources through equity or debt","Selling assets to improve liquidity","Taking out a loan to finance running operating costs"],explanation:"According to the textbook, investment is using financial resources to acquire assets. Raising the financial resources themselves, on the other hand, is called financing.",correctIndex:0},{question:"Loopy has invested too much capital from Loopy's Candy Store in an oversized packaging machine and now can't pay her supplier invoices. What is this state of being unable to pay called?",options:["Liquidation","Insolvency","Amortisation","Recession"],explanation:"Insolvency means a company is unable to pay: payment obligations can no longer be met. Wrong investment decisions can, in the worst case, lead to insolvency.",correctIndex:1},{question:'According to the textbook, what is meant by "investment management"?',options:["Only monitoring and documenting the capital costs of an investment after it has been carried out","Raising equity and debt for new investment projects","The systematic planning, decision-making, implementation and monitoring of investments","The ongoing valuation of securities held in the company's current assets"],explanation:"According to the textbook, investment management covers the systematic planning, decision-making, implementation and monitoring of investments as part of the investment process in a company. Steering an investment project is called investment management.",correctIndex:2},{question:"Loopy invests surplus money from Loopy's Candy Store in securities. What type of investment is this by type of asset?",options:["Real investment","Intangible investment","Expansion investment","Financial investment"],explanation:"By type of asset, a distinction is made between real investment (physical assets, e.g. a machine), financial investment (financial assets, e.g. securities) and intangible investment (non-physical assets, e.g. patents). Securities are therefore a financial investment.",correctIndex:3},{question:"Loopy replaces an old, slow packaging machine in Loopy's Candy Store with a new, much more efficient model to increase productivity. What is the reason for this investment?",options:["Rationalisation investment","Replacement investment","New investment","Expansion investment"],explanation:"A rationalisation investment replaces an old machine with a new, more efficient one. This distinguishes it from a pure replacement investment, where a machine that can no longer be used is simply replaced by a similar one.",correctIndex:0},{question:"According to the textbook's diagram, in which order do the four phases of the investment process run?",options:["Investment decision – investment planning – monitoring – implementation","Investment planning – investment decision – implementation – monitoring","Implementation – investment planning – investment decision – monitoring","Monitoring – implementation – investment decision – investment planning"],explanation:"The investment process usually runs in the phases investment planning, investment decision, implementation and monitoring, as the textbook shows with the example of buying a stove for the hotel ever grün.",correctIndex:1},{question:'According to the textbook, which activity belongs to the "investment planning" phase of the investment process?',options:["Making the purchase decision","Placing the order","Getting quotes","Collecting experience for the future"],explanation:"Investment planning includes reporting the investment need, setting decision criteria and getting quotes. The purchase decision belongs to the investment decision, the order to implementation.",correctIndex:2},{question:`Loopy is considering two new refrigerated display cases for Loopy's Candy Store and compares them using, among others, the criteria "acquisition cost" and "environmental friendliness". What are these two types of criteria correctly called?`,options:["Both are quantitative criteria","Acquisition cost = qualitative, environmental friendliness = quantitative","Both are qualitative criteria","Acquisition cost = quantitative, environmental friendliness = qualitative"],explanation:"Quantitative criteria (hard facts) are factors that can be measured in numbers, such as costs, revenue or profitability. Qualitative criteria (soft facts) are factors that cannot be measured in numbers, such as environmental friendliness or market position.",correctIndex:3},{question:"Which key question does the profitability comparison method answer as one of the static investment appraisal methods?",options:["Which investment has the highest return on the capital tied up in it?","Which investment causes the lowest costs?","Which investment earns the highest profit?","With which investment does the invested capital flow back the fastest?"],explanation:"The five static methods each answer their own key question: cost comparison (lowest costs), profit comparison (highest profit), profitability comparison (highest return on capital), payback method (fastest return) and scoring method (most points).",correctIndex:0},{question:"Which two cost blocks make up the total costs considered in the cost comparison method?",options:["Acquisition cost and selling price","Running operating costs and capital costs","Cost of equity capital and cost of debt capital","Fixed costs and contribution margin"],explanation:"The cost comparison method considers the investment's running operating costs (variable and fixed operating costs) and capital costs (imputed interest and imputed depreciation).",correctIndex:1},{question:"How is imputed depreciation calculated in the cost comparison method?",options:["(acquisition cost + residual value) : 2 × interest rate","(acquisition cost + residual value) : useful life","(acquisition cost − residual value) : useful life","acquisition cost × interest rate : useful life"],explanation:"Imputed depreciation is the difference between acquisition value and residual value, spread over the useful life: (acquisition cost − residual value) : useful life.",correctIndex:2},{question:"Loopy compares two company cars for Loopy's Candy Store deliveries using the cost comparison method. Car A has an acquisition cost of €31,250.00 and a residual value after 5 years of €10,200.00. The imputed interest rate is 5% p.a. How much is the imputed interest per year?",options:["€781.25","€2,072.50","€1,562.50","€1,036.25"],explanation:"Imputed interest = (acquisition cost + residual value) : 2 × interest rate = (31,250.00 + 10,200.00) : 2 × 5% = 20,725.00 × 5% = €1,036.25. The values come from the textbook example comparing two company cars (C5 Tourer and C5 saloon).",correctIndex:3},{question:"Loopy compares two vehicle models for delivering her chocolates from Loopy's Candy Store using the cost comparison method. At 35,000 km a year, model A has total costs of €14,469.38, model B only €13,491.79 despite higher acquisition costs. Which model should Loopy choose?",options:["Model B, because it has the lower total costs","Model A, because it has the lower acquisition costs","Both equally, because the cost comparison total is identical","Model A, because petrol vehicles are always cheaper"],explanation:"In the cost comparison method, the alternative with the lowest total costs is chosen. Although model B has higher acquisition costs, its annual total costs of €13,491.79 are lower than model A's €14,469.38 (textbook example: comparing a C5 Tourer and C5 saloon for an insurance company's fleet).",correctIndex:0},{question:"Loopy is deciding which of two new packaging machines to buy for Loopy's Candy Store. Machine 1 has fixed costs (imputed depreciation + interest) of €221,000.00 per year and variable costs of €150.00 per machine hour; machine 2 has fixed costs of €292,500.00 and variable costs of €110.00 per machine hour. What is the critical quantity?",options:["1,030.00 hours","1,787.50 hours","2,500.00 hours","625.00 hours"],explanation:"Critical quantity = difference in fixed costs : difference in variable costs = (292,500.00 − 221,000.00) : (150.00 − 110.00) = 71,500.00 : 40.00 = 1,787.50 hours. Below this utilisation machine 1 is cheaper, above it machine 2 (values from the textbook example of two printing machines).",correctIndex:1},{question:"Which disadvantage does the textbook attribute to the cost comparison method?",options:["It considers too much data and is therefore too time-consuming for small firms","It can only be used if the exact utilisation is known in advance","Only average values for one period are considered and revenue is ignored","It considers only qualitative criteria such as environmental friendliness"],explanation:"According to the textbook, disadvantages include that only average values for one period are used, different revenues are not taken into account and the time value of money is not included.",correctIndex:2},{question:"How does the profit comparison method extend the cost comparison method?",options:["By taking employee satisfaction into account","By taking the capital employed into account","By taking the payback period into account","By taking revenue into account"],explanation:"The profit comparison method adds revenue to the cost comparison method: profit = revenue − total costs. It is used e.g. when the capacity or quality of the investment goods differs.",correctIndex:3},{question:"Loopy is considering whether to renovate Loopy's Candy Store on a small or large scale. Small option: cost €250,000.00, running operating costs €75,000.00/year, useful life 10 years, interest rate 4%, revenue €180,000.00. Large option: cost €600,000.00, running operating costs €186,000.00/year, useful life 6 years, interest rate 4%, revenue €430,000.00. According to the profit comparison method, what annual profit does the large option earn?",options:["€132,000.00","€75,000.00","€98,000.00","€144,000.00"],explanation:"Profit = revenue − (imputed interest + imputed depreciation + running operating costs) = 430,000.00 − (12,000.00 + 100,000.00 + 186,000.00) = €132,000.00. In comparison, the small option only earns €75,000.00 profit (textbook example: room renovation at hotel ever grün).",correctIndex:0},{question:"What is the formula for calculating profitability in the profitability comparison method?",options:["Profitability = (profit + imputed depreciation) : acquisition cost × 100","Profitability = (profit + imputed interest) : average capital employed × 100","Profitability = revenue : (total costs + imputed interest) × 100","Profitability = average capital employed : (profit + imputed interest) × 100"],explanation:"Profitability = (profit + imputed interest) : average capital employed × 100, where average capital employed = (acquisition cost + residual value) : 2.",correctIndex:1},{question:"For the small renovation option of Loopy's Candy Store (cost €250,000.00, profit €75,000.00, imputed interest €5,000.00) the profitability comparison gives 64%; for the large option (cost €600,000.00, profit €132,000.00, imputed interest €12,000.00) only 48%. Which conclusion does Loopy correctly draw from this?",options:["The profitability comparison confirms exactly the result of the profit comparison","The small option is the worse choice in any case, because it brings the lower absolute profit","The large option earns more, but the small one gives a higher return on capital employed","The large option is more profitable, because its absolute profit is almost twice as high"],explanation:"Unlike the profit comparison, where the large option does better with €132,000.00, the profitability comparison gives a better result for the small option at 64% than for the large one at 48%, because the capital employed is taken into account.",correctIndex:2},{question:"What additional advantage does the profitability comparison method offer over the profit comparison method?",options:["It takes the time value of money into account by discounting the returns","It needs no figures on costs and revenue and is therefore quicker","It also shows after how many years the capital employed has flowed back in full","Investments with different amounts of capital employed can be compared well"],explanation:"Because the profitability comparison sets profit in relation to the capital employed, investments with different amounts of capital employed can also be compared well.",correctIndex:3},{question:"Which two methods of payback calculation does the textbook distinguish?",options:["Average method and cumulative method","Net present value method and annuity method","Cost comparison and profit comparison method","Direct and indirect method"],explanation:"In payback calculation, a distinction is made between the average method (annual cash inflow is the same) and the cumulative method (annual cash inflow differs).",correctIndex:0},{question:"For the small renovation option of Loopy's Candy Store: cost €250,000.00, annual profit €75,000.00, imputed depreciation €25,000.00. How many years does payback take using the average method?",options:["3.33 years","2.50 years","10.00 years","1.50 years"],explanation:"Payback period = (acquisition cost − residual value) : (annual profit + imputed depreciation) = 250,000.00 : (75,000.00 + 25,000.00) = 250,000.00 : 100,000.00 = 2.50 years (textbook example: room renovation at hotel ever grün, four-star category).",correctIndex:1},{question:"According to the textbook, which of the following statements correctly describes a limit of static investment appraisal methods?",options:["They always consider several periods over the whole useful life","They consider only qualitative criteria and no costs or revenue","Only one period is considered, which is seen as representative of the others","They take the time value of money into account through compounding or discounting"],explanation:"One limit of static methods is that only one period is considered and seen as representative of the whole useful life. This weakness is only overcome by dynamic methods with several periods, which take the time value of money into account.",correctIndex:2},{question:"What especially distinguishes the scoring method from the other static investment appraisal methods?",options:["It considers only hard facts and rates them with points","It only calculates the critical quantity between two investment alternatives","It rates only qualitative criteria and deliberately ignores costs","It combines quantitative and qualitative criteria and rates them with points"],explanation:"The scoring method takes both quantitative and qualitative criteria into account in investment decisions, which are rated with points. The alternative with the highest score is chosen.",correctIndex:3},{question:"According to the textbook, what is the first step in using the scoring method?",options:["Set the decision criteria for assessing the investments","Multiply each criterion's points by its weighting","Add up the weighted points for each investment into a total","Rate each criterion for every investment on a scale from 1 to 5"],explanation:"The first step of the scoring method is setting the decision criteria. Then come weighting, rating, multiplying and adding up the points.",correctIndex:0},{question:"In a scoring method comparing two electric delivery vehicles for Loopy's Candy Store, vehicle A reaches a weighted total score of 2.6, vehicle B one of 3.15 (rating scale 1 to 5 points per criterion). Which vehicle should Loopy choose?",options:["Vehicle A, because as in the cost comparison method, lower values are better in the scoring method","Vehicle B, because the alternative with the highest score meets the requirements best","Neither, because a difference of 0.55 points is too small to decide","Vehicle A, because it has the lower acquisition costs, regardless of the total score"],explanation:"In the scoring method, the alternative with the highest weighted total score is chosen. With 3.15 compared with 2.6 points, vehicle B meets the requirements best according to the calculation (values from the textbook example comparing two electric shuttle buses for a hotel).",correctIndex:1}],finanzmanagement:[{question:"In business administration, what is meant by the term 'financing'?",options:["Planning and providing the capital needed to start, keep up and expand business activities.","Distributing the profits earned to a company's owners at the end of the financial year.","Recording all payments in the accounts on an ongoing basis and preparing the company's income statement.","Selecting and assessing investment alternatives using the cost or profit comparison method."],explanation:"Financing means planning and providing the capital (financial resources) needed to start, keep up and expand a company's business activities.",correctIndex:0},{question:"Which three key financing goals of companies does the textbook name?",options:["Growth, revenue and market share","Liquidity, profitability and independence","Efficiency, effectiveness and sustainability","Creditworthiness, security and financial flexibility"],explanation:"Companies' financing goals are closely linked to their business goals. A distinction is made between liquidity, profitability and independence.",correctIndex:1},{question:"Loopy wants to make sure her Candy Store can always pay all open invoices on time. Which financing goal is she mainly pursuing?",options:["Profitability","Independence","Liquidity","Creditworthiness"],explanation:"Liquidity means a company's ability to meet its payment obligations on time and in full.",correctIndex:2},{question:"According to the textbook, which formula is used to calculate a company's profitability?",options:["Profitability = revenue ÷ capital employed × 100","Profitability = capital employed ÷ profit × 100","Profitability = profit − capital employed","Profitability = profit ÷ capital employed × 100"],explanation:"Profitability shows the return earned on the capital employed in the company: profitability = profit ÷ capital employed × 100.",correctIndex:3},{question:"The Austrian circuit board maker ATSS invested large sums in new production equipment and achieved a 10% return the previous year. Because sales were lower than expected, the company had to take out an expensive bank loan for the new equipment due to a lack of liquid funds. Which goal conflict does this example show?",options:["Goal conflict between liquidity and profitability","Goal conflict between independence and creditworthiness","Goal conflict between equity and debt financing","Goal conflict between internal and external financing"],explanation:"If too much liquid money is invested, profitability rises, but the money may then be missing for other purposes - if too much liquid money is held back, earnings are lost. As the example shows, such a goal conflict between liquidity and profitability can even make expensive debt financing necessary.",correctIndex:0},{question:"According to the textbook, which three key tasks does financial management include?",options:["Setting selling prices, planning advertising and managing sales","Determining the ongoing financing need, choosing the financing type and carrying it out","Planning staff needs, managing production and checking product quality","Preparing the balance sheet and income statement, filing tax returns and running the monthly payroll"],explanation:"Key tasks of financial management are working out the ongoing financing need through financial planning, deciding on the right form of financing and carrying out the financing (organising payments and raising capital).",correctIndex:1},{question:"Loopy reinvests retained profits from selling her sweets directly back into her business instead of paying them out to herself. Which type of financing is she using?",options:["Loan financing","Participation financing","Self-financing","Subsidy financing"],explanation:"In self-financing the company receives additional equity from its own profits that are not paid out - it is a form of internal equity financing.",correctIndex:2},{question:"Tischlerei Hölzinger GmbH bought a plot of land in 1982 for €200,000.00, which has been shown in the balance sheet at this acquisition value ever since. Today the land has a market value of €1,500,000.00. How large is the hidden reserve in the land?",options:["€200,000.00","€500,000.00","€1,500,000.00","€1,300,000.00"],explanation:"The hidden reserve is the difference between the actual market value and the lower book value in the balance sheet: €1,500,000.00 − €200,000.00 = €1,300,000.00. It only becomes visible as profit when the land is sold (hidden self-financing).",correctIndex:3},{question:"What is a venture capital company?",options:["A financing company that gives young companies equity (usually over €200,000.00) with no fixed repayment or interest.","A bank that gives young companies only short-term overdrafts, secured by the usual collateral and charged at normal interest.","A private individual who invests smaller sums (approx. €50,000.00 to €150,000.00) in a young company.","A state funding body that gives start-ups non-repayable grants and checks that they are used as intended."],explanation:"A venture capital company is a financing company that provides a young company with equity (usually over €200,000.00) without fixed repayment or interest and in return receives rights to information, control and a say.",correctIndex:0},{question:"How does a business angel differ from a venture capital company?",options:["A business angel only invests in companies listed on the stock exchange and never in young start-ups.","A business angel is a private individual, not a financing company, and usually invests smaller sums.","A business angel only provides debt capital in the form of loans and never receives any shares.","Unlike a venture capital company, a business angel always demands fixed interest."],explanation:"Like a venture capital company, a business angel has a direct stake in the company, but is a private individual rather than a financing company; business angels usually invest smaller sums (approx. €50,000.00 to €150,000.00) than venture capital companies.",correctIndex:1},{question:"Loopy agrees with a business angel that he will invest €60,000.00 in expanding her Candy Store and receive 25% of the company shares in return. What type of financing is this?",options:["Debt financing through a private loan from the business angel","Internal financing through self-financing from retained profits","Equity financing through the participation of a business angel","Debt financing through issuing a bond"],explanation:"The business angel invests directly and receives a share in the company in return - this is equity financing (external financing) through a new co-owner, just like the textbook example with €60,000.00 for 25% of the shares.",correctIndex:2},{question:"Which form of crowdfunding counts as debt in the balance sheet because the investors receive interest for it?",options:["Donation-based crowdfunding","Reward-based crowdfunding","Equity-based crowdfunding","Lending-based crowdfunding"],explanation:"In lending-based crowdfunding ('money for interest') investors receive interest on their investment, which is why it counts as debt - unlike equity-based crowdfunding, which counts as equity.",correctIndex:3},{question:"What is meant by 'going public'?",options:["Converting into an AG and going to the stock exchange with a first share issue (IPO)","Converting a company into a GmbH and taking in new shareholders","Issuing a bond on the stock exchange for the first time in order to raise debt capital","Taking out several overdrafts at different banks at the same time"],explanation:"Going public means converting a company into an AG and then listing it on the stock exchange, i.e. the first issue of shares (initial public offering, IPO), which brings the company fresh equity.",correctIndex:0},{question:"How are subsidies (grants) described in the textbook?",options:["As low-interest loans from public bodies that must be repaid after a few years","As 'free money' from public bodies that does not have to be paid back","As capital contributions from business angels in return for shares","As bonds that the state issues to finance companies"],explanation:"Subsidies (grants) are 'free money' paid to companies by the federal government, provinces, municipalities, the EU or the Chamber of Commerce; they are only checked to see that they are used for the intended purpose, but they never cover the whole capital need.",correctIndex:1},{question:"According to the textbook, which feature applies to debt?",options:["It is available to the company without a time limit and without interest payments.","The capital providers share directly in the success and have a say in decisions.","It must be repaid at a certain time and interest must be paid on it.","In insolvency, creditors bear the full risk of loss just like equity providers."],explanation:"Debt is available to a company only for a limited time, must be repaid at a certain time, and the borrowers must pay interest that doesn't depend on success; creditors usually have no say and bear a more limited risk of loss in bankruptcy than equity providers.",correctIndex:2},{question:"Why does the textbook describe the financing effect of provisions as hard to plan?",options:["Because provisions always lead to an immediate payment of the full amount to third parties.","Because provisions may only be made for assets that have already been depreciated.","Because provisions may only be made with the approval of the tax office.","Because it is unclear how much or when a provision will lead to a payment."],explanation:"Companies make a provision for expected expenses where the reason is known, but it is unclear how much or when the provision will be used to settle future liabilities - that's why it is counted as long-term financing.",correctIndex:3},{question:"Which five criteria for distinguishing types of loan does the textbook name?",options:["Lender, what the lender provides, term, purpose and loan security","Interest rate, loan currency, borrower's creditworthiness, repayment type and region","Industry, legal form, number of employees, revenue and profit","Lender, loan amount, interest rate, purpose and type of repayment"],explanation:"Loans are needed for different reasons and needs. Accordingly, the types of loan also differ and can be distinguished by lender, what the lender provides, term, purpose and loan security.",correctIndex:0},{question:"According to the textbook, how are loan terms divided?",options:["short-term up to 5 years, medium-term 5-10 years, long-term more than 10 years","short-term up to 1 year, medium-term 1-5 years, long-term more than 5 years","short-term up to 3 months, medium-term 3-12 months, long-term over 1 year","short-term up to 2 years, medium-term 2-8 years, long-term over 8 years"],explanation:"By term, a distinction is made between short-term loans (up to 1 year), medium-term loans (1-5 years) and long-term loans (more than 5 years).",correctIndex:1},{question:"Into which three types is loan security basically divided in the textbook?",options:["Guarantee, assignment of receivables (cession) and mortgage","Personal security, real security and retention of title","Personal security, real security and credit insurance","Overdraft, loan and guarantee credit"],explanation:"For many loans the bank asks for security. This can be divided into loan securities - subdivided into personal security (e.g. guarantee) and real security (e.g. retention of title, cession, lien) - and credit insurance.",correctIndex:2},{question:"Which type of guarantee is the most far-reaching for the creditor, because they can freely choose whether to demand payment first from the guarantor or from the main debtor?",options:["Deficiency guarantee","Ordinary guarantee","Personal security in general","Joint and several guarantee"],explanation:"With the joint and several guarantee ('guarantor as payer') the creditor can choose whom to demand payment from first - it is therefore more far-reaching than the ordinary guarantee (where the creditor must first try the main debtor) and the deficiency guarantee (limited, only liable for the remainder left after enforcement).",correctIndex:3},{question:"According to the textbook, which real security gives the lender the most security, while retention of title gives the least?",options:["Lien","Assignment of receivables (cession)","Guarantee","Credit insurance"],explanation:"In terms of how much is transferred, real securities range from retention of title (least security) through assignment of receivables (cession) to the lien, which gives the most security.",correctIndex:0},{question:"How does the textbook distinguish between hard facts and soft facts in a credit check?",options:["Hard facts are personal traits such as payment behaviour, soft facts are material factors such as income and assets.","Hard facts are material factors such as income or assets, soft facts personal traits such as payment behaviour.","Hard facts only concern companies as borrowers, soft facts only private individuals.","By law, hard facts must be checked, while soft facts may not be taken into account in a credit check."],explanation:"Hard facts are factors based on material characteristics, e.g. monthly income or the profit and asset situation. Soft facts are factors based on personal characteristics, e.g. past payment behaviour, credibility or professional qualifications.",correctIndex:1},{question:"According to the textbook, in which order are loan transactions with banks handled?",options:["Loan agreement - loan application - credit check - loan monitoring","Credit check - loan application - loan monitoring - loan agreement","Loan application - credit check - loan agreement - loan monitoring","Loan monitoring - loan agreement - credit check - loan application"],explanation:"Loan transactions are handled in four steps: first the borrower makes a loan application, then the bank checks the documents and creditworthiness (credit check), then the loan agreement and security documents are signed (loan agreement), and finally the bank continuously monitors creditworthiness (loan monitoring).",correctIndex:2},{question:"What characterises a current account credit (overdraft)?",options:["A long-term investment loan that is repaid in equal monthly instalments over many years","A loan amount paid out once in full to finance fixed assets over the long term","A short-term loan given only to private individuals without a current account","A short-term, revolving credit line on the current account for liquidity shortages"],explanation:"A current account credit is a short-term cash credit of a certain amount: the holder of a current account can use the agreed credit line at any time on a revolving basis. It mainly serves as bridging finance for short-term liquidity shortages.",correctIndex:3},{question:"Which three types of loans does the textbook distinguish by type of repayment?",options:["Bullet loan, instalment loan and annuity loan","Current account credit, supplier credit and customer credit","Short-, medium- and long-term loan at a fixed interest rate","Deficiency guarantee, guarantee loan and aval credit"],explanation:"Loans are distinguished by type of repayment: with a bullet loan there is no repayment during the term and the whole sum is repaid at the end; with an instalment loan the repayment amount stays constant while the interest falls; with an annuity loan the monthly payment (annuity) stays constant, with the repayment share rising and the interest share falling.",correctIndex:0},{question:"Hotel ever.grün takes out an annuity loan of €42,000.00 at 6.5% p.a. interest with a 10-year term to buy an electric shuttle bus. According to the repayment plan, in the 1st year interest is €2,639.27 and repayment is €3,083.61. What is the annuity (total annual payment) in the 1st year?",options:["€2,639.27","€5,722.82","€3,083.61","€38,916.39"],explanation:"The annuity is the sum of interest and repayment: €2,639.27 + €3,083.61 = €5,722.82. With an annuity loan this total annual payment stays constant over the whole term.",correctIndex:1},{question:"What is a guarantee credit?",options:["The lender immediately pays the borrower a sum of money, which has to be repaid in monthly instalments.","The lender buys the borrower's receivables from third parties before they fall due, in return for a fee.","The lender takes on liability for its customer's obligations to third parties without paying out money.","The lender lets the borrower use assets in return for a fee, without selling them to the borrower."],explanation:"With a guarantee credit, the lender (usually a bank) takes on liability for its customer's obligations to third parties - only if it is actually called upon does it become a cash credit. Examples are the advance payment guarantee and the warranty guarantee.",correctIndex:2},{question:"Loopy orders packaging material from a supplier and gets the goods delivered immediately, but only has to pay the invoice in a few weeks according to the agreed payment term. Which type of financing is she using without realising it?",options:["Customer credit","Current account credit","Guarantee credit","Supplier credit"],explanation:"With supplier credit, the customer receives goods already delivered or services already performed but only pays later within the payment term granted. The seller often offers a discount as an incentive to pay faster.",correctIndex:3},{question:"A supplier offers the following payment terms: '8 days 3% discount, 30 days net.' If the discount is not used, the calculated annual interest rate (using the formula annual interest rate = discount in % ÷ (payment term − discount period in days) × 360) is about:",options:["49.09% p.a.","3.00% p.a.","36.00% p.a.","24.55% p.a."],explanation:"Annual interest rate = 3 ÷ (30 − 8) × 360 = 3 ÷ 22 × 360 ≈ 49.09% p.a. Not using the discount is therefore very expensive - usually more expensive than a bank loan to pre-finance the discounted payment.",correctIndex:0},{question:"What is factoring?",options:["The company takes out a long-term loan from its own bank and assigns its customer receivables to the bank as security.","The company sells customer receivables to a factoring bank before they are due and gets the money earlier, minus fees.","The company rents movable assets to other companies in return for an ongoing fee.","The company gives its customers longer payment terms and so finances their purchases itself."],explanation:"In factoring, a company sells receivables from customers to a factoring bank before they are due and so receives the money owed earlier - minus the factoring bank's fees. A distinction is made between open factoring (the customer is informed) and silent factoring (the customer doesn't find out).",correctIndex:1},{question:"What is the main difference between operating leasing and finance leasing?",options:["In operating leasing the lessee always bears all maintenance and risk costs like an owner.","Unlike operating leasing, finance leasing can be cancelled at short notice at any time without a penalty.","They differ mainly in the lessee's rights and duties, e.g. regarding maintenance and risk.","Operating leasing counts as a rental contract, whereas finance leasing is a classic loan according to the textbook."],explanation:"Leasing is not a loan, but a contract for letting someone use assets for a fee. Operating leasing and finance leasing differ mainly in the lessee's rights and duties, e.g. regarding maintenance, cancellation and bearing risk.",correctIndex:2},{question:"What characterises mezzanine capital?",options:["A form of short-term overdraft financing that, in insolvency, is paid before all other debt","Pure equity provided by business angels with full say, which in insolvency is paid last of all","A secured loan with an especially low, fixed interest rate that is always repaid with priority","A mix of equity and debt financing with profit-linked interest, subordinated in insolvency"],explanation:"Mezzanine capital is a mix of equity and debt financing: it usually requires less security, is provided long-term, has profit-linked interest and in payment difficulties (insolvency) is only entitled after debt has been served (subordinated capital) - e.g. as a subordinated loan, silent partnership or subordinated bond.",correctIndex:3}],"finanzplan-analyse":[{question:"According to the textbook, for a company to stay liquid in the long term, it must be true in the long term that...",options:["total outflows are greater than total inflows in the long run","total inflows are greater than or equal to total outflows","equity is greater than debt in every year","cash flow stays constant at zero"],explanation:"A company only stays liquid if in the long term: total inflows are greater than or equal to total outflows. Otherwise there is a shortfall that has to be covered.",correctIndex:1},{question:'How is cash flow defined in the chapter "Financial plan and financial analysis"?',options:["as the sum of all open customer receivables at the end of a period","as a company's profit according to the income statement","as the surplus of cash a company generates in a certain period","as the difference between fixed and current assets"],explanation:"Cash flow is the surplus of cash a company generates in a certain period and is an important early warning tool.",correctIndex:2},{question:"Which measure does the textbook recommend when there is a cash surplus in the financial plan?",options:["Extending the payment terms agreed with suppliers","Taking out an additional bank loan","Making more use of discounts from suppliers","Selling assets that aren't needed"],explanation:"With a cash surplus, one option is to make more use of discounts from suppliers. Longer payment terms, extra loans and selling assets, on the other hand, are measures for a shortfall.",correctIndex:2},{question:"Which balancing measure does the textbook name for a threatened cash shortfall?",options:["Increasing private withdrawals","Building open reserves","Investing surplus funds short-term","Taking out an additional bank loan"],explanation:"With a shortfall, one option is to take out a bank loan. Increased private withdrawals, building reserves and investing money, on the other hand, are typical measures for a surplus.",correctIndex:3},{question:"According to the textbook, how large should a sensible liquidity reserve be?",options:["one to two average daily outflows","two to three average monthly outflows","six to twelve average monthly outflows","exactly the amount of equity"],explanation:"According to the textbook, a liquidity reserve of two to three average monthly outflows helps cushion crises caused by planning mistakes or unexpected events.",correctIndex:1},{question:"What purpose do long-term financial plans, which according to the textbook cover two to six years, serve?",options:["mainly securing short-term liquidity and the company's ability to pay day to day","securing creditworthiness and planning the capital structure and investments","daily monitoring of account balances and open customer invoices","calculating the monthly advance VAT return and payroll taxes"],explanation:"Long-term financial plans (two to six years) serve to secure creditworthiness, plan the capital structure and coordinate larger investment projects, while short-term plans mainly secure liquidity.",correctIndex:1},{question:"Loopy draws up a financial plan for the fourth quarter for her Candy Store. In the textbook example, the available overdraft is...",options:["€80,000.00","€14,000.00","€40,000.00","€4,000.00"],explanation:'In the business case "Financial plan" the available overdraft is €40,000.00; it can be used to cover short-term shortfalls.',correctIndex:2},{question:"In the same business case, the opening cash balance at the start of a month may not fall below a certain amount. How much is it?",options:["€83,000.00","€5,000.00","€55,000.00","€14,000.00"],explanation:"The opening cash balance at the start of each month should not fall below €14,000.00 so that liquidity stays secure.",correctIndex:3},{question:"Into which four groups are the selected key figures for financial analysis divided in the textbook?",options:["Revenue figures, cost figures, profit figures and loss figures","Asset structure, capital structure, earnings-related figures, assets-to-capital relationship","Liquidity figures, profitability figures, growth figures and market figures","Staff structure, cost structure, financial figures and the relationship between revenue and costs"],explanation:"The textbook distinguishes key figures for asset structure, capital structure, earnings-related key figures and key figures on the relationship between assets and capital.",correctIndex:1},{question:"According to the textbook, which statement about fixed asset intensity is correct?",options:["Fixed asset intensity = current assets / total assets × 100","Retail businesses are typically regarded as current-asset-intensive","High fixed asset intensity always increases a company's flexibility","Fixed asset intensity is always judged the same regardless of the industry"],explanation:"Retail businesses, the textile industry, gastronomy or banks with a high share of receivables are current-asset-intensive, while e.g. industrial or energy companies are fixed-asset-intensive. The formula is fixed assets / total assets × 100.",correctIndex:1},{question:"According to the textbook, from which equity ratio is a company considered very well capitalised?",options:["from 5%","from 10%","from 20%","from 30%"],explanation:"The equity ratio should be at least 20%; from 30% it is considered very good. A ratio below 10% is critical, a negative ratio means a risk of insolvency.",correctIndex:3},{question:"How is gearing calculated and which rule of thumb does the textbook give?",options:["Debt / equity; a ratio of 1 : 2 is considered very good today","Equity / debt; a ratio of 2 : 1 is considered critical today","Debt / total capital; a value over 100% is considered very good","Equity / total capital; a value below 20% is considered very good"],explanation:"Gearing = debt / equity. In the past 1:1 was the aim; today 1:2 is already considered very good and 1:3 good.",correctIndex:0},{question:'Which notional debt repayment period does the textbook rate as "very good"?',options:["under 3 years","under 7 years","under 15 years","over 15 years"],explanation:"A notional debt repayment period of under three years is very good, under five years good. From 15 years, according to the quick test table, the risk of insolvency rises.",correctIndex:0},{question:'What does the "golden financing rule" say about fixed asset coverage?',options:["Fixed asset coverage should be at least 100%","Equity must always be higher than debt","Liquidity ratio 1 should always be 100%","Short-term liabilities may never be higher than 50% of current assets"],explanation:"Fixed asset coverage = (equity + long-term debt) / fixed assets × 100 should be at least 100% – this is the golden financing rule.",correctIndex:0},{question:"According to the textbook, in which range should liquidity ratio 1 (cash liquidity) ideally be?",options:["between 0% and 10%","between 20% and 50%","between 100% and 120%","between 150% and 200%"],explanation:"Liquidity ratio 1 = cash / short-term liabilities × 100. Values between 20% and 50% are the aim; at 100% all short-term debts would be covered immediately by cash.",correctIndex:1},{question:"Which target value does the textbook give for liquidity ratio 3?",options:["50% to 100%","100% to 120%","150% to 200%","exactly 300%"],explanation:"According to the textbook, liquidity ratio 3 (cash + short-term receivables + stock, divided by short-term liabilities) should be between 150% and 200%.",correctIndex:2},{question:"According to the textbook, how is working capital calculated?",options:["Equity minus short-term liabilities","Current assets (without prepaid expenses) minus short-term liabilities","Fixed assets minus long-term debt","Current assets (including prepaid expenses) minus long-term liabilities"],explanation:"Working capital = current assets (without prepaid expenses) − short-term liabilities. A positive value shows that part of current assets is financed long-term.",correctIndex:1},{question:"Loopy uses the balance sheet data from the textbook example for her Candy Store (equity €558,000.00, total capital €1,166,000.00). What is the equity ratio?",options:["approx. 87.39%","approx. 52.14%","approx. 47.86%","approx. 103.43%"],explanation:"Equity ratio = equity / total capital × 100 = 558,000.00 / 1,166,000.00 × 100 ≈ 47.86%. 52.14% is the debt ratio, 87.39% the fixed asset intensity and 103.43% the fixed asset coverage of the same example.",correctIndex:2}],"businessplan-3jg":[{question:"According to the textbook, what position does financial planning have within a business plan?",options:["It is only an optional appendix of little importance to investors","Next to the executive summary it is the most important part of the plan","It completely replaces the executive summary and therefore always comes first","Banks consider it less important than marketing planning"],explanation:"According to the textbook, next to the executive summary, financial planning is the most important part of the business plan, because potential investors check this area especially closely.",correctIndex:1},{question:"According to the textbook, what do investors pay special attention to in financial planning, among other things?",options:["only the fittings and location of the planned shop","the capital need, what it is needed for and where the capital comes from","the number of social media followers the company has","a revenue forecast that is as high as possible, regardless of how realistic it is"],explanation:"Investors such as banks or business angels check, among other things, the capital need, realistic sales forecasts, expected returns and the break-even analysis.",correctIndex:1},{question:"According to the textbook, what does a break-even analysis determine?",options:["the amount of VAT and income tax due each year","at what output quantity revenue covers all costs","how many employees are needed for the planned output","at what selling price a company's profit is highest"],explanation:"A break-even analysis determines at what output quantity or revenue income covers costs, so that the company is profitable.",correctIndex:1},{question:"According to the textbook, which four partial plans does a financial plan in a business plan usually contain?",options:["Marketing planning, location planning, staff and training planning, tax planning","Sales, material and staff expenses, investment and financing, profit and liquidity","SWOT analysis, target group analysis, competitor analysis, location analysis","Balance sheet planning, income statement planning, tax and levy planning, exit and succession planning"],explanation:"A financial plan usually consists of sales planning, planning material and staff expenses, investment and financing planning, and profit and liquidity planning.",correctIndex:1},{question:"According to the textbook, for what period is a financial plan in a business plan usually drawn up?",options:["for one month","for three to five years","for ten to twenty years","only for the current quarter"],explanation:"According to the textbook, a financial plan in a business plan is usually drawn up for a planning horizon of three to five years.",correctIndex:1},{question:"According to the textbook, how is planned revenue calculated?",options:["Fixed costs divided by contribution margin","Net selling price multiplied by the planned sales quantity","Cost of goods multiplied by the number of planned opening days","Equity multiplied by the turnover rate"],explanation:"Planned revenue = net selling price × planned sales quantity. Planned revenue must be realistic, because it feeds into many other partial plans.",correctIndex:1},{question:"For her Candy Store's first business year, Loopy plans with 110 customers per opening day, 300 opening days a year and average spending of €4.50 per customer – like the textbook example. What is the planned revenue?",options:["€110,000.00","€148,500.00","€156,978.00","€135,000.00"],explanation:"Planned revenue = 110 customers × 300 opening days × €4.50 = €148,500.00 (1st business year). €156,978.00 is the value for the 2nd business year after customer growth and price increases.",correctIndex:1},{question:"Which annual growth rates for customers and prices does the textbook example use for the first three business years?",options:["10% customer growth and 5% inflation","4% customer growth and 2% inflation","2% customer growth and 4% inflation","0% customer growth and 3% inflation"],explanation:"In the business case, annual customer growth of 4% is carefully estimated and selling prices are calculated with an inflation rate of 2%.",correctIndex:1},{question:"According to the textbook, how are subsidies received that don't have to be repaid (e.g. €8,000.00 for investments) treated in the accounts?",options:["they are booked in full as income immediately in the year they are received","they are spread over the useful life and recorded as other income","they are deducted directly from equity and not spread","they are never recorded in the income statement"],explanation:'In the accounts, subsidies are spread over the useful life and recorded each year proportionally (in the example €8,000.00 / 5 years = €1,600.00) as "other income".',correctIndex:1},{question:"According to the textbook, what equity ratio do banks usually require at least when giving loans?",options:["5%","10%","20%","50%"],explanation:"According to the textbook, equity is important for getting debt. When giving loans, banks usually require an equity ratio of at least 20%.",correctIndex:2},{question:"According to the textbook, how is interest on an overdraft calculated?",options:["only on the amount of credit actually used in each month","on the full credit line, even if it is not fully used","only based on the company's previous year's profit","there is generally no interest on an overdraft"],explanation:"According to the textbook, the interest costs of an overdraft are calculated on the full credit line, even if the credit is not fully used.",correctIndex:1},{question:"According to the textbook, what is the basic difference between profit planning and liquidity planning?",options:["They are identical in content and only differ in the period covered","Profit planning shows income and expenses, liquidity planning shows cash flows","Profit planning shows cash flows, liquidity planning shows income and expenses","Profit planning is only done once when the business is founded"],explanation:"Profit planning (planned income statement) compares income and expenses, while liquidity planning shows whether there is enough cash for ongoing obligations – an accounting profit does not automatically mean cash.",correctIndex:1},{question:"Which example does the textbook give of a payment being made without an accounting expense arising?",options:["the annual depreciation of a machine or a building","repaying a loan or a private withdrawal","selling goods on credit","booking other income"],explanation:"According to the textbook, repaying a loan and private withdrawals lead to a payment, but not to an accounting expense.",correctIndex:1},{question:"How does the textbook define minimum revenue (break-even point)?",options:["the revenue at which the maximum possible profit is made","the point at which there is neither profit nor loss","the revenue in the first full month of sales","the industry's average annual revenue"],explanation:"Minimum revenue (break-even point/profit threshold) marks the point at which income fully covers costs and there is neither profit nor loss.",correctIndex:1},{question:"According to the textbook, how is the contribution margin ratio calculated?",options:["Fixed costs / revenue × 100","Contribution margin / revenue × 100","Revenue / fixed costs × 100","Variable costs / contribution margin × 100"],explanation:"Contribution margin ratio = contribution margin / revenue × 100. Break-even revenue is then fixed costs / contribution margin ratio.",correctIndex:1},{question:"For her Candy Store (like the café example in the textbook) Loopy calculates break-even revenue with fixed costs of €86,900.00 and a contribution margin ratio of 64.98%. What amount does she get?",options:["€86,900.00","approx. €133,733.46","approx. €148,500.00","approx. €96,500.00"],explanation:"Break-even revenue = fixed costs / contribution margin ratio = 86,900.00 / 0.6498 ≈ €133,733.46. Only from this revenue are private withdrawals and income tax also covered.",correctIndex:1},{question:"According to the textbook, for sole traders what counts as fixed costs included in the break-even calculation?",options:["a notional owner's salary excluding private withdrawals and income tax","a notional owner's salary including private withdrawals and income tax","only depreciation","the profit increases expected over the next three business years"],explanation:"In sole proprietorships and partnerships a notional owner's salary is often used, which covers the owners' living costs (private withdrawals) and income tax.",correctIndex:1},{question:"In the example of Bäckerei Laurent-Gerhard GmbH, ovens and kitchen equipment worth €20,000.00 are depreciated over a useful life of 10 years. What is the annual depreciation?",options:["€20,000.00","€4,000.00","€2,000.00","€1,000.00"],explanation:"Annual depreciation = acquisition value / useful life = €20,000.00 / 10 years = €2,000.00.",correctIndex:2}]}};export{e as default};
